/* 11-sinf Tarbiya — «Baxt va muvaffaqiyat sirlari» (2021). I–IV boblar */
window.T11 = window.T11 || [];
T11.push(
{id:"m1",n:"1-mavzu",t:"Vatan taraqqiyotiga men ham mas’ulman",b:1,
 map:{c:"Vatan taraqqiyotiga men ham mas’ulman",br:[
  {t:"Daxldorlik",e:"🤝",k:["aloqadorlik","sheriklik","birlashtiradi"],x:"Daxldorlik — biror faoliyat yoki jarayonga aloqadorlik va sheriklik. U insonlarni birlashtiradi, burch va mas’uliyatni kuchaytiradi."},
  {t:"Munosib hissa",e:"🏅",k:["Anvarbek Rahmatov","olimpiada medallari","Vatan dovrug‘i"],x:"Qorako‘l tumanidagi o‘quvchi Anvarbek Rahmatov xalqaro olimpiadalarda medallar olgan; maqsadi — Vatan dovrug‘ini dunyoga tanitish."},
  {t:"Qurbaqa rivoyati",e:"🐸",k:["o‘rmon yong‘ini","og‘zida suv","yaxshilik tomoni"],x:"Qurbaqa oz suv bilan o‘tni o‘chira olmasligini biladi, ammo harakati bilan yaxshilik tomonida turganini ko‘rsatadi."},
  {t:"Hayot zanjiri",e:"🧵",k:["har bir ipning o‘rni","har odamning vazifasi","zanjir uzilmasin"],x:"Matodagi bitta chirigan ipdan yirtilish boshlanadi. Hayot zanjirida ham har kimning o‘rni bor."},
  {t:"Oila oldidagi mas’uliyat",e:"👧",k:["«Oqibat» hikoyasi","aka va singil","kasb egalari"],x:"7 yoshli bolakay singlisini tashlab ketmaydi. Shifokor, chegarachi, dispetcher kabi kasb egalarining mas’uliyati ham hammaga daxldor."}]},
 q:[
 {t:"m",q:"Darslikda daxldorlik qanday izohlanadi?",a:["Faoliyatga aloqadorlik va sheriklik","Faqat o‘z manfaatini himoya qilish","Boshqalarning ishidan chetda turish","Berilgan buyruqni so‘zsiz bajarish"],e:"Daxldorlik — biror faoliyat yoki jarayonga aloqadorlik va sheriklikdir."},
 {t:"m",q:"Fuqaro Vatan taqdiriga daxldorlik hissi bilan yashasa, nima kuchayadi?",a:["Burch va mas’uliyati","Loqaydligi va beparvoligi","Shaxsiy manfaatparastligi","Boshqalarga qaramligi"],e:"Daxldorlik tuyg‘usi jamiyat oldidagi burch va mas’uliyatni kuchaytiradi."},
 {t:"m",q:"Konstitutsiyaning darslikda keltirilgan 51-moddasi fuqarolarning qaysi majburiyati haqida?",a:["Soliq va yig‘imlarni to‘lash","Harbiy xizmatni o‘tab berish","Atrof-muhitni asrab-avaylash","Tarixiy yodgorliklarni saqlash"],e:"Moddada fuqarolar qonun bilan belgilangan soliqlar va mahalliy yig‘imlarni to‘lashga majburligi aytilgan."},
 {t:"m",q:"Anvarbek Rahmatov qaysi fanga ixtisoslashgan maktabda o‘qiydi?",a:["Matematika","Informatika","Adabiyot va tarix","Kimyo va biologiya"],e:"U Qorako‘l tumanidagi matematikaga ixtisoslashgan maktabning o‘quvchisi."},
 {t:"m",q:"Yong‘in rivoyatida qurbaqa o‘z harakatini qanday izohladi?",a:["Yaxshilik tomonida turganini bildirishini aytdi","O‘tni yolg‘iz o‘zi o‘chira olishiga ishonishini aytdi","Qarg‘aning maqtovini eshitmoqchi ekanini aytdi","O‘rmondan tezroq qochib ketmoqchi ekanini aytdi"],e:"Qurbaqa suvi bilan o‘tni o‘chirib bo‘lmasligini bilsa ham, yaxshilik tarafida turganini ko‘rsatgan."},
 {t:"m",q:"«Muhimi – zanjirning uzilishiga sen sababchi bo‘lib qolmasligingdir» hikmati nimaga undaydi?",a:["O‘z o‘rni va vazifasiga mas’ul bo‘lishga","Boshqalarning xatosini qidirib yurishga","Qiyin ishlardan imkon qadar qochishga","Faqat kattalarning ko‘rsatmasini kutishga"],e:"Har bir odamning hayot zanjirida o‘z o‘rni va vazifasi bor."},
 {t:"m",q:"«Oqibat» hikoyasida bolakay nega oila bilan ketolmasligini aytdi?",a:["Kichik singlisini tashlab keta olmasligi uchun","Yangi maktabga borishni istamasligi uchun","Do‘stlaridan ajralib qolishdan qo‘rqqani uchun","Tarbiyachisi bunga ruxsat bermagani uchun"],e:"U akalik burchini va ota-onasiga bergan va’dasini aytdi. Oila aka-singilni birga farzandlikka oldi."},
 {t:"m",q:"«Kimning xalqqa foydasi tegib, shu tufayli halovat topsa, o‘sha – yaxshi odam» — kimning fikri?",a:["Yusuf Xos Hojib","Mahmud Zamaxshariy","Alisher Navoiy","Abu Ali ibn Sino"],e:"Bu hikmat darslikda Yusuf Xos Hojib nomi bilan berilgan."},
 {t:"tf",q:"Daxldorlik hissi insonlarni bir-biridan uzoqlashtiradi.",a:false,e:"Darslikka ko‘ra daxldorlik hissi insonlarni birlashtiradi."},
 {t:"tf",q:"Darslikka ko‘ra, mas’uliyatni zimmasiga olish insonni ulug‘ darajaga yetkazadi.",a:true,e:"Mas’uliyatni olish insonga fayz-u kamol baxsh etadi."},
 {t:"tf",q:"Zebo yo‘l chetida yotgan kishiga befarq bo‘lmay, odamlarni yordamga chorlagan.",a:true,e:"Zebo bekatdagilarga vaziyatni tushuntirdi, natijada «Tez yordam» chaqirildi."},
 {t:"f",q:"Vatan taraqqiyotiga o‘quvchi sifatida qanday hissa qo‘sha olasiz? Kamida ikkita misol keltiring.",e:"A’lo o‘qish va kasb egallash, mahalla ishlarida qatnashish, tabiatni asrash, oilada o‘z vazifasini bajarish — daxldorlik shu ishlarda ko‘rinadi."}]},

{id:"m2",n:"2-mavzu",t:"Erkin va farovon hayot mazmuni",b:1,
 map:{c:"Erkin va farovon hayot mazmuni",br:[
  {t:"Ikki qanot",e:"⚖️",k:["moddiy olam","ma’naviy olam","yuksalish"],x:"Moddiy va ma’naviy olam uyg‘unlashib qo‘sh qanotga aylansa, inson, jamiyat va davlat yuksaladi."},
  {t:"Mangulikka daxldor",e:"🍇",k:["Mahmud Mirzayev","bog‘dorchilik","300 dan ortiq asar"],x:"Mahmud Mirzayev agronomlikdan akademiklikkacha yo‘l bosdi; 2013-yilda ilmiy tadqiqot instituti unga nomlandi."},
  {t:"Boylik va kambag‘allik",e:"💰",k:["yonma-yon yuradi","o‘rin almashadi","oqillik"],x:"Boylikka haddan ortiq quvonmaslik, yo‘qchilikda ko‘p qayg‘urmaslik, har ishdan xulosa chiqarish kerak."},
  {t:"Ma’naviyat",e:"🌿",k:["o‘zaro ishonch","hurmat","poydevor"],x:"Ma’naviyat — ishonch, hurmat, ezgu intilish va ibratli fazilatlar majmuasi; ijtimoiy munosabatlar poydevori."},
  {t:"Ezgulik va pul",e:"💡",k:["Suqrot","G‘afur G‘ulom","mehnat va axloq"],x:"Suqrot: pul ezgulik tug‘dirmaydi, aksincha ezgulik tufayli boylikka erishiladi."}]},
 q:[
 {t:"m",q:"Qaysi ikki omil uyg‘unlashsa, inson va jamiyat hayotida yuksalish bo‘ladi?",a:["Moddiy va ma’naviy olam","Boylik va yuqori mansab","Sport va ko‘ngilochar hordiq","Shuhrat va shaxsiy manfaat"],e:"Moddiy va ma’naviy olam qo‘sh qanotga aylanganda o‘sish va yuksalish yuz beradi."},
 {t:"m",q:"Moddiy-ma’naviy uyg‘unlik buzilsa, darslikka ko‘ra nima yuz beradi?",a:["Ma’naviy-axloqiy munosabatlar tanazzulga uchraydi","Ishlab chiqarish va iqtisodiyot o‘z-o‘zidan gullab ketadi","Insonlarning qadr-qimmati yanada yuksalib boradi","Jamiyatda o‘zaro ishonch va hurmat kuchayadi"],e:"Aks holda axloqiy munosabatlar tanazzulga uchrab, inson sha’ni poymol bo‘ladi."},
 {t:"m",q:"Mahmud Mirzayev yoshligidan nimaga qiziqqan?",a:["Ko‘chat payvandlash va bog‘dorchilikka","Me’morchilik va naqqoshlikka","Chorvachilik va veterinariyaga","Aviatsiya va koinot tadqiqotiga"],e:"U ko‘chat payvand qilish, yangi nav yaratishga qiziqqan."},
 {t:"m",q:"Mahmud Mirzayev rahbarligida tayyorlangan «O‘zbekiston ampelografiyasi» nima haqida?",a:["Uzumning turlari va navlari","Poliz ekinlari kasalliklari","Tuproq turlari va xossalari","Sug‘orish inshootlari tarixi"],e:"Ampelografiya — uzum turlari va navlari haqidagi ish."},
 {t:"m",q:"«Pul ezgulikni tug‘dirmaydi...» deb boshlanadigan hikmat muallifi kim?",a:["Suqrot","Arastu","Konfutsiy","Sitseron"],e:"Suqrot: ezgulik tufayli odamlar pul va boshqa boyliklarga ega bo‘ladi."},
 {t:"m",q:"G‘afur G‘ulom fikriga ko‘ra, baxtga erishuvning stimuli nima?",a:["Axloq mukammalligi","Mo‘l-ko‘l boylik","Tasodifiy omad","Yuqori lavozim"],e:"Shoir baxtni axloq va mehnat bilan bog‘laydi: axloq mukammalligi baxtga undovchi kuch."},
 {t:"m",q:"Ma’naviyat jamiyatdagi siyosiy-ijtimoiy munosabatlar uchun qanday ta’riflangan?",a:["Mazmun va sifatni belgilovchi poydevor","Faqat bayramlarda eslanadigan an’ana","Iqtisodiyotga bog‘liq bo‘lmagan bezak","Ayrim kishilargagina tegishli odat"],e:"Prezident ta’rifida ma’naviyat — munosabatlar mazmuni va sifatini belgilaydigan poydevor."},
 {t:"m",q:"Barcha sohada ijobiy natijaga erisha oladigan odamga nima xos?",a:["Bilim, kasb malakasi va huquqiy savod","Faqat katta boylik va tanish-bilishlar","Qonunlarni chetlab o‘ta olish mahorati","Boshqalarning mehnatiga tayanish odati"],e:"Bilim, tajriba, kasb malakasi yetarli, qonun, huquq va majburiyatlarini bilgan odam yutuqqa erishadi."},
 {t:"tf",q:"Darslikda keltirilgan fikrga ko‘ra, boylik o‘tkinchidir.",a:true,e:"«Boyligingga quvonma, u o‘tkinchidir» deyiladi."},
 {t:"tf",q:"Mahmud Mirzayev hech qanday ilmiy faoliyat bilan shug‘ullanmagan.",a:false,e:"U tadqiqotlar olib borgan va 300 dan ortiq ilmiy asar yozgan."},
 {t:"tf",q:"Ma’naviyatning iqtisodiy rivojlanishga aloqasi yo‘q.",a:false,e:"Darslikda ma’naviyat ishlab chiqarish va iqtisodiy rivojlanish bilan uzviy bog‘liq deyiladi."},
 {t:"f",q:"Nima uchun faqat moddiy boylik bilan farovon hayot qurib bo‘lmaydi? Fikringizni misol bilan asoslang.",e:"Ma’naviyatsiz boylik uzoqqa bormaydi: ishonch, hurmat, halollik, bilim va kasb bo‘lmasa, farovonlik barqaror bo‘lmaydi."}]},

{id:"m3",n:"3–4-mavzu",t:"Dadil qadamlar bilan katta hayot sari",b:1,
 map:{c:"Dadil qadamlar bilan katta hayot sari",br:[
  {t:"Vaqt qadri",e:"⏳",k:["samarali mehnat","lahza qadri","Navoiy hikmati"],x:"Zoye ketgan vaqt qaytmaydi. Tiriklikning asosi — aql, davomiyligi — samarali mehnat."},
  {t:"O‘ziga baho",e:"🪞",k:["oyna qiyosi","xolislik","o‘z portreti"],x:"O‘ziga noxolis baho qiyshiq oyna kabi noto‘g‘ri aks beradi."},
  {t:"Yo‘l ko‘rsatuvchilar",e:"👨‍🏫",k:["ota-ona","ustozlar","duo va tilak"],x:"Sharqda ota-ona va ustozlar alohida e’zozlanadi; bu muqaddas qadriyatlarning tamal toshi."},
  {t:"Iqtidorli yoshlar",e:"🎓",k:["olimpiada","xalqaro tanlov","tinimsiz izlanish"],x:"Madina Samatboyeva, Fayzullo Yahyoyev, Farrux Fattoyev kabi yoshlar o‘qish va izlanish bilan yutuqqa erishgan."},
  {t:"Fuqarolik va qadriyat",e:"🗳️",k:["18 yosh","saylov huquqi","meros soat"],x:"18 yoshga to‘lgan fuqaro saylash huquqiga ega. Soat rivoyati: haqiqiy qadriyatning bahosi yillar o‘tgan sari oshadi."}]},
 q:[
 {t:"m",q:"Insonning o‘ziga bergan bahosi darslikda nimaga qiyoslanadi?",a:["Oynaga","Taroziga","Soatga","Chiroqqa"],e:"Noto‘g‘ri baho qiyshiq oyna kabi noto‘g‘ri aksni ko‘rsatadi."},
 {t:"m",q:"«Hayotda muvaffaqiyatga erishish uchun uch narsa kerak» — Rumiy qaysilarni aytgan?",a:["Diqqat, intizom va harakat","Boylik, mansab va shuhrat","Omad, tanish va imkoniyat","Kuch, jasorat va g‘ayrat"],e:"Jaloliddin Rumiy: diqqat, intizom va harakat."},
 {t:"m",q:"Xitoy hikmatiga ko‘ra, 100 yil foyda berishini ko‘zlagan kishi nima qilishi kerak?",a:["Farzand tarbiyalashi","Daraxt ekishi","Sholi ekishi","Mustahkam uy qurishi"],e:"Bir yil uchun sholi, 50 yil uchun daraxt, 100 yil uchun farzand tarbiyasi."},
 {t:"m",q:"Abu Nasr Forobiy fikricha, insonning boshqa mavjudotlardan farqi nimada?",a:["Aql-idrokliligida","Jismoniy kuchida","Tashqi ko‘rinishida","Uzoq umr ko‘rishida"],e:"Forobiy: insonning farqi uning aql-idrokliligida."},
 {t:"m",q:"Inson hayoti va jismoniy tuzilishini geografik omillarga bog‘liq deb ko‘rsatgan alloma kim?",a:["Abu Rayhon Beruniy","Abu Ali ibn Sino","Abu Hamid G‘azzoliy","Abu Nasr Forobiy"],e:"Bu fikr darslikda Beruniy nomi bilan keltirilgan."},
 {t:"m",q:"Saylov kodeksiga ko‘ra, kim saylash huquqiga ega?",a:["Saylov kuni 18 yoshga to‘lgan fuqaro","Saylov yili 16 yoshga kirgan har bir o‘quvchi","Faqat oliy ma’lumotli va ishlayotgan fuqaro","Faqat 21 yoshdan oshgan oilali fuqaro"],e:"Saylovlar umumiy: saylov kuni 18 ga to‘lgan fuqarolar saylaydi."},
 {t:"m",q:"Ota o‘g‘liga meros soatni turli joyga olib bortirib, nimani anglatmoqchi edi?",a:["Ayrim qadriyatlar bahosi yillar o‘tgani sari oshadi","Eski buyumlarni tezroq arzonga sotib yuborish kerak","Soatsozlar har doim eng to‘g‘ri bahoni aytadi","Har qanday narsa vaqt o‘tishi bilan qadrsizlanadi"],e:"Ota bebaho milliy qadriyatlarni asrab, avlodga yetkazishni uqtirdi."},
 {t:"m",q:"Olimlardan Farrux Fattoyev fizik bo‘lib yetishishiga nima sabab bo‘lganini aytadi?",a:["Maktabdagi barcha fanlarga bir xil qiziqishi","Faqat bitta fan bilan shug‘ullanib yurgani","Tasodifan chet elga ishga borib qolgani","Bolaligida sport bilan jiddiy shug‘ullangani"],e:"U barcha fanlarga bir xilda qiziqqanini ta’kidlaydi."},
 {t:"tf",q:"G‘azzoliy fikricha, muammo va xavf-xatarlarni yengib o‘tgan shaxs baxtlidir.",a:true,e:"G‘azzoliy: muammolarni bartaraf etgan shaxsgina baxtlidir."},
 {t:"tf",q:"O‘zbekiston Saylov kodeksiga ko‘ra, saylov huquqi fuqaroning millati va tiliga qarab farqlanadi.",a:false,e:"Fuqarolar millati, tili, dini va boshqa belgilaridan qat’i nazar teng saylov huquqiga ega."},
 {t:"tf",q:"Ajdodlarimiz farzandlariga nasl-nasabini o‘rgatishga e’tibor bermagan.",a:false,e:"Aksincha, ular farzandlarga ota-bobolar nasabini o‘rgatganlar."},
 {t:"f",q:"Katta hayotda qoqilmaslik uchun vaqtingizni qanday rejalashtirasiz va qaysi fazilatlarni shakllantirasiz?",e:"Kun tartibi, maqsad va reja; ilm olish, mehnat; diqqat, intizom, qat’iy iroda, rostgo‘ylik va yaxshilikka intilish."}]},

{id:"m4",n:"5-mavzu",t:"Oila mas’uliyati, sha’ni va qadri",b:1,
 map:{c:"Oila mas’uliyati, sha’ni va qadri",br:[
  {t:"Mo‘jaz Vatan",e:"🏠",k:["ilk tushunchalar","ma’naviyat","avlodlar kamoli"],x:"Dunyoqarash, e’tiqod va eng pok tuyg‘ular oila bag‘rida shakllanadi."},
  {t:"Tabiatdagi buvilar",e:"🐘",k:["odamlar","kitlar","fillar"],x:"Filchalar 5 yoshgacha buvilari bilan yuradi, katta fillar ularga yashash qoidalarini o‘rgatadi."},
  {t:"Ota mehri",e:"🤲",k:["baland ko‘tarish","peshonadan o‘pish","duo"],x:"Otaning har bir harakatida ezgu tilak bor: «Bugun seni suysam, ertaga senga suyanaman»."},
  {t:"Oila vazifasi",e:"🧩",k:["tartib-qoida","tejamkorlik","to‘g‘riso‘zlik"],x:"Hamjihatlik va ishonch kuchli oilada samimiy, mehribon insonlar voyaga yetadi."},
  {t:"Fitrat fikri",e:"📜",k:["ichki intizom","totuvlik","millat saodati"],x:"Oilaviy munosabatlar zaiflashsa, millat saodati shubha ostida qoladi."}]},
 q:[
 {t:"m",q:"Oilaga berilgan ta’riflardan qaysi biri darslikda keltirilgan?",a:["Oila — mo‘jaz Vatan","Oila — vaqtinchalik bekat","Oila — iqtisodiy shartnoma","Oila — shaxsiy ishxona"],e:"Savollarda «Oila mo‘jaz Vatandir» ta’rifi beriladi."},
 {t:"m",q:"Inson qalbidagi ilk hayotiy tushuncha va tasavvurlar qayerda shakllanadi?",a:["Oila bag‘rida","Ish jamoasida","Ijtimoiy tarmoqda","Sport to‘garagida"],e:"Eng sof tuyg‘u va ilk tasavvurlar aynan oilada shakllanadi."},
 {t:"m",q:"Olimlarga ko‘ra, tabiatda odamlardan tashqari qaysi jonivorlar oilasida «bobo» yoki «buvi» bor?",a:["Kitlar va fillar","Sherlar va bo‘rilar","Burgutlar va laylaklar","Otlar va tuyalar"],e:"Darslikdagi «Bilasizmi?» ruknida odamlar, kitlar va fillar aytilgan."},
 {t:"m",q:"Ota go‘dak farzandini baland ko‘targanda qanday tilak bildiradi?",a:["Mendan-da ulug‘ bo‘l","Doim yonimda qol","Tezroq boyib ket","Hech qayoqqa ketma"],e:"Bu — «mendan-da ulug‘ bo‘l, bolam» degani."},
 {t:"m",q:"Harbiy xizmatga kuzatayotib ota o‘g‘lining belidan ko‘tarishi nimani anglatadi?",a:["Vatan xizmatiga bog‘lagan beling mustahkam bo‘lsin","Xizmatdan tezroq qaytib, uy ishlariga yordam ber","Boshqalardan kuchli ekaningni hammaga ko‘rsatib qo‘y","Qiynalsang, xizmatni tashlab uyga qaytaver"],e:"Bu harakat Vatan xizmatida mustahkam bo‘lishga tilakdir."},
 {t:"m",q:"Qaysi sifatlar oilaning azaliy vazifasi sifatida kamol toptirilgan?",a:["Saranjomlik, tejamkorlik, to‘g‘riso‘zlik","Isrofgarchilik, manmanlik, maqtanchoqlik","Loqaydlik, erinchoqlik, o‘zboshimchalik","Hasadgo‘ylik, ayyorlik, manfaatparastlik"],e:"Tajriba orttirish, saranjomlik, tejamkorlik, qat’iylik va to‘g‘riso‘zlik."},
 {t:"m",q:"Abdurauf Fitratga ko‘ra, bir oilaning saodati nimaga bog‘liq?",a:["Xalqning ichki intizomi va totuvligiga","Faqat xonadondagi boylik miqdoriga","Qo‘shni mamlakatlar bilan savdo hajmiga","Oila a’zolarining soni va yoshiga"],e:"Fitrat: saodat va izzat xalqning ichki intizomi va totuvligiga bog‘liq."},
 {t:"m",q:"Darsdagi hikmatga ko‘ra, yurtni obod, umrni ziyoda qiladigan amallar qaysi?",a:["Silai rahm, xushxulqlik, yaxshi qo‘shnichilik","Katta to‘y qilish, qimmat sovg‘a berish","Yolg‘iz yashash, hech kimga aralashmaslik","Ko‘p safar qilish, tez-tez ko‘chib yurish"],e:"Qarindoshlarga silai rahm, xushxulqlik va yaxshi qo‘shnichilik."},
 {t:"tf",q:"Darslikka ko‘ra, katta yoshli fillar yosh fillar tarbiyasiga aralashmaydi.",a:false,e:"Ular yosh fillarga ozuqa topish va tuzoqdan himoyalanishni shaxsan o‘rgatadi."},
 {t:"tf",q:"Fitratga ko‘ra, oilaviy munosabatlarning zaiflashishi millat hayotiga ta’sir qilmaydi.",a:false,e:"Bunda millatning saodati va hayoti shubha ostida qoladi."},
 {t:"tf",q:"Ota «ona qizim» deb murojaat qilishi farzandning ulug‘ ishlaridan suyunishi bilan bog‘liq.",a:true,e:"Farzandining ulug‘ ishini ko‘rgan ota o‘g‘lini «ota o‘g‘il», qizini «ona qizim» deb suyadi."},
 {t:"f",q:"Oilangiz baxtli va mustahkam bo‘lishi uchun sizning zimmangizda qanday mas’uliyat bor?",e:"Ota-onani hurmat qilish, uka-singillarga g‘amxo‘rlik, uy ishlariga yordam, rostgo‘ylik, oila sha’nini asrash."}]},

{id:"m5",n:"6-mavzu",t:"Ibrat maskani",b:2,
 map:{c:"Ibrat maskani",br:[
  {t:"Mahalla kuchi",e:"🏘️",k:["tarbiya","jipslik","issiq-sovuq"],x:"Mahalla aholini jipslashtiradi, poklik va xolislikni qaror toptiradi, odamlar bir-biridan xabar oladi."},
  {t:"Isomjon bobo o‘giti",e:"👴",k:["qizlarni tanish","qadrdonlik","inson insonga kerak"],x:"Bobo qizlarni ajdodlariga o‘xshatib taniydi: mahalladoshlar qarindoshdek bo‘lib ketadi."},
  {t:"Hashar",e:"🧹",k:["obodonlik","birdamlik","mehnatdan qochish"],x:"Hashar odamlarni birlashtiradi; «pulini to‘lasangiz» deyish esa mahalla ruhiga zid holat sifatida muhokamaga qo‘yiladi."},
  {t:"Temuriylar tozaligi",e:"💧",k:["hovuz va ariqlar","toza suv","kasallik oldini olish"],x:"Amir Temur davrida mahallada tozalikka, ayniqsa suv tozaligiga katta e’tibor berilgan."},
  {t:"Navoiy ibrati",e:"🖋️",k:["rabot va ko‘priklar","xalq g‘ami","naf yetkazish"],x:"Navoiy butun faoliyatini xalq farovonligiga bag‘ishladi: xalqqa qilingan yaxshilik o‘zingga ko‘proq foydadir."}]},
 q:[
 {t:"m",q:"Isomjon bobo mahalladoshlik haqida nima dedi?",a:["Odamlar bir-biriga qarindoshdek bo‘lib ketadi","Har kim faqat o‘z hovlisini bilishi yetarli","Qo‘shnining ishiga umuman qiziqmaslik kerak","Mahalla faqat hujjat olish uchun zarur"],e:"«Odamlar bir-biriga qon-qarindosh bo‘lib ketishadi... Inson insonga kerak»."},
 {t:"m",q:"Mahalla qanday maskan deb ataladi?",a:["Bir-biridan xabar olinadigan tabarruk maskan","Faqat savdo-sotiq qilinadigan gavjum maskan","Odamlar vaqtincha tunab o‘tadigan maskan","Faqat rasmiy majlislar o‘tkaziladigan maskan"],e:"Odamlar bir-birining issiq-sovug‘i va g‘am-tashvishidan xabar oladi."},
 {t:"m",q:"«Men mardikor emasman» hikoyasida yigit nimani bahona qildi?",a:["Oliygohni tugatganini","Betob bo‘lib qolganini","Yoshi hali kichikligini","Ishga kech qolayotganini"],e:"U «oliygohni tugatganman» deb chiqindi tashlashdan bosh tortdi."},
 {t:"m",q:"Muarrix Xondamir Navoiy Xurosonda nechta rabot qurdirganini qayd etgan?",a:["52 ta","20 ta","16 ta","116 ta"],e:"52 ta rabot, 20 ta hovuz va 16 ta ko‘prik tilga olingan."},
 {t:"m",q:"«Nafing agar xalqqa beshak durur, Bilki, bu naf o‘zungga ko‘prak durur» misralari mazmuni qaysi?",a:["Xalqqa yaxshilik qilgan o‘zi ko‘proq foyda ko‘radi","Yaxshilikni faqat evaziga haq olib qilish kerak","Avval o‘z foydangni o‘ylab, keyin boshqani o‘yla","Xalqqa qilingan yordam kishiga zarar keltiradi"],e:"Navoiy: boshqaga naf yetkazish, aslida, o‘zingga foyda."},
 {t:"m",q:"Navoiy davrida qaysi shahar katta madaniy markazga aylandi?",a:["Hirot","Buxoro","Samarqand","Shahrisabz"],e:"Uning davrida Hirotda ilm-fan va ma’rifat gullab-yashnadi."},
 {t:"m",q:"Amir Temur davrida yuqumli kasalliklarning oldini olishda nimaga katta ahamiyat berilgan?",a:["Tozalikka, ayniqsa suv tozaligiga","Bozorlarni butunlay yopib qo‘yishga","Shahar devorlarini balandlatishga","Chet ellik savdogarlarni haydashga"],e:"Ariq va hovuzlardagi suvlar nihoyatda toza tutilgan."},
 {t:"m",q:"Mahalla qanday munosabatlarga asoslanishi darslikdagi hikmatda aytilgan?",a:["O‘zaro ishonch, yordam va himoya","O‘zaro raqobat va manfaat","Qat’iy buyruq va jazolash","Befarqlik va aralashmaslik"],e:"«Mahalla o‘zaro ishonch, yordam va himoya munosabatlariga asoslanadi»."},
 {t:"tf",q:"Mahalla hashar kabi tadbirlarni amalga oshirish vositasi hamdir.",a:true,e:"Mahalla milliy urf-odat, an’ana va hasharlarni amalga oshirish vositasi."},
 {t:"tf",q:"Navoiy insonni uning ijtimoiy kelib chiqishi va mavqeiga qarab ulug‘lagan.",a:false,e:"U ijtimoiy kelib chiqishi va mavqeidan qat’i nazar insonni ulug‘lagan."},
 {t:"tf",q:"Ashraf aka hasharda oilasi bilan eng faol qatnashdi.",a:false,e:"U mardikor yollashni, pulini berib qo‘yishni taklif qildi."},
 {t:"f",q:"Mahallangiz obod bo‘lishi uchun o‘zingiz bajara oladigan ikki-uch ishni va rejangizni yozing.",e:"Hasharda qatnashish, ko‘chat ekib parvarishlash, keksalarga yordam, ozodalikni saqlash; har biriga vaqt va sheriklar belgilanadi."}]},

{id:"m6",n:"7-mavzu",t:"Bag‘rikenglik",b:2,
 map:{c:"Bag‘rikenglik",br:[
  {t:"Davlat bag‘rikengligi",e:"🕊️",k:["yetti tilda ta’lim","64 bola","do‘stlik"],x:"O‘zbekistonda ta’lim yetti tilda olib boriladi; 2019-yilda Yaqin Sharqdan 64 bola olib kelindi."},
  {t:"Uch non rivoyati",e:"🍞",k:["qarz uzish","qarzga berish","burch"],x:"Bir non ota-onaga (qarz uzish), biri farzandlarga (qarzga), biri o‘ziga."},
  {t:"Totuvlikka g‘ov",e:"🚫",k:["tajovuzkor millatchilik","shovinizm","fashizm"],x:"Bu illatlar tuzog‘iga tushgan jamiyat halokatga yuz tutadi."},
  {t:"Millat va dinlar",e:"🌍",k:["130 dan ortiq millat","16 konfessiya","30-iyul"],x:"Yurtda ko‘p millat va konfessiya vakillari totuv yashaydi; 30-iyul — Xalqlar do‘stligi kuni."},
  {t:"Rezolyutsiya",e:"📘",k:["BMT","«Ma’rifat va diniy bag‘rikenglik»","2018-yil"],x:"Prezident tashabbusi bilan taklif etilgan rezolyutsiya 2018-yil 12-dekabrda yakdil qabul qilindi."}]},
 q:[
 {t:"m",q:"Uch non rivoyatida xaridor «qarzimga beraman» degan non kimga tegishli edi?",a:["Ota-onasiga","Farzandlariga","Novvoyning o‘ziga","Qo‘shni oilaga"],e:"Ota-onasi uni bolaligida boqqani uchun bu qarzni uzish."},
 {t:"m",q:"Xaridor «qarzga beraman» degan non bilan nimani nazarda tutgan?",a:["Farzandlarini boqishini","Do‘stlariga ulashishini","Bozorda qayta sotishini","Ertangi kunga saqlashini"],e:"Farzandlar ham bir kun kelib qarzlarini uzadi."},
 {t:"m",q:"«Yer yuzida aka-ukadek yashashni o‘rganmadik» degan fikr kimga tegishli?",a:["Martin Lyuter King","Mahatma Gandi","Nelson Mandela","Lev Tolstoy"],e:"Martin Lyuter King: uchish va suzishni o‘rgandik, aka-ukadek yashashni emas."},
 {t:"m",q:"Millatlararo totuvlikka eng xatarli to‘siq nima?",a:["Tajovuzkor millatchilik va shovinizm","Turli tillarda ta’lim berib borilishi","Milliy bayramlarning ko‘p nishonlanishi","Dinlararo muloqot va hamkorlik"],e:"Darslikda aynan shu ikki g‘oya eng xatarli to‘siq deyilgan."},
 {t:"m",q:"Darslikka ko‘ra, O‘zbekistonda ta’lim nechta tilda olib boriladi?",a:["Yettita","Beshta","O‘nta","Uchta"],e:"O‘zbekcha darsliklar yana oltita tilga tarjima qilinadi."},
 {t:"m",q:"O‘zbekistonda Xalqlar do‘stligi kuni qaysi sana?",a:["30-iyul","16-noyabr","21-mart","12-dekabr"],e:"Xalqaro do‘stlik kuni — 30-iyul Xalqlar do‘stligi kuni deb e’lon qilindi."},
 {t:"m",q:"«Ma’rifat va diniy bag‘rikenglik» rezolyutsiyasini BMTning nechta a’zo davlati qabul qilgan?",a:["193 ta","182 ta","130 ta","72 ta"],e:"2018-yil 12-dekabrda 193 a’zo mamlakat yakdil qabul qildi."},
 {t:"m",q:"Mitropolit Vladimir yurtimizdagi dinlararo munosabatni qanday baholagan?",a:["Ziddiyat ham, tushunmovchilik ham yo‘qligini aytgan","Do‘stlik faqat rasmiy uchrashuvlarda sezilishini aytgan","Ruhoniylar bilan imomlar kam uchrashishini aytgan","Yordam so‘rash juda qiyin bo‘lib qolganini aytgan"],e:"U ruhoniylar va imomlar o‘rtasida do‘stlik baland ekanini ta’kidlagan."},
 {t:"tf",q:"Dunyo dinlarining barchasi ezgulik g‘oyalariga asoslanadi.",a:true,e:"Dinlar halollik, tinchlik, yaxshilik va bag‘rikenglikka da’vat etadi."},
 {t:"tf",q:"Imom Buxoriy rivoyatiga ko‘ra, Payg‘ambar (a.s.) o‘zga din vakilining janozasiga o‘rnidan turib hurmat ko‘rsatgan.",a:true,e:"Sababi — u ham inson ekanligi."},
 {t:"tf",q:"XIX asrda Rossiyadan majburan ko‘chirilgan dehqonlarga mahalliy aholi yordam bermagan.",a:false,e:"Iyeromonax Xariton guvohligicha, mahalliy aholi ularga rahmdillik qilgan."},
 {t:"f",q:"Bag‘rikeng inson qanday bo‘ladi? Kundalik hayotingizdan misol keltiring.",e:"O‘zga millat, din va fikrni hurmat qiladi, kechirimli va oqibatli bo‘ladi; masalan, boshqa millatli sinfdoshga yordam beradi, nizoni murosa bilan hal qiladi."}]},

{id:"m7",n:"8–9-mavzu",t:"Ksenofobiya",b:2,
 map:{c:"Ksenofobiya",br:[
  {t:"Tushuncha",e:"😨",k:["ksenos — begona","fobos — qo‘rquv","hadik"],x:"Ksenofobiya — begona, notanish narsa yoki shaxsdan haddan ortiq qo‘rqish va nafratlanish."},
  {t:"Yangilikdan qo‘rqish",e:"🔭",k:["Kopernik","Galiley","kartoshka"],x:"Olimlar ixtirolari shubha bilan kutilgan; XXI asrda qo‘rquv obyekti o‘zgardi, xolos."},
  {t:"Irqchilik",e:"✊",k:["Ku-kluks-klan","AQSH","terror"],x:"Fuqarolar urushidan keyin tuzilgan yashirin guruh qora tanlilarga tazyiq o‘tkazgan."},
  {t:"Diniy ksenofobiya",e:"☪️",k:["islamofobiya","xristianofobiya","yudofobiya"],x:"Ekstremistik guruhlar dinni niqob qilishi islomofobiyani kuchaytiradi."},
  {t:"Huquqiy himoya",e:"📑",k:["Konvensiya","1965-yil","Milliy harakatlar rejasi"],x:"Irqiy kamsitishning barcha shakllarini tugatish konvensiyasiga O‘zbekiston 1995-yilda qo‘shilgan."}]},
 q:[
 {t:"m",q:"«Ksenofobiya» atamasidagi «ksenos» so‘zi nimani anglatadi?",a:["Begona, notanish","Qo‘rquv, hadik","Nafrat, g‘azab","Din, e’tiqod"],e:"Yunoncha ksenos — begona, fobos — qo‘rquv."},
 {t:"m",q:"Ku-kluks-klan guruhi qachon va qayerda tashkil topgan?",a:["AQSHdagi fuqarolar urushidan keyin","Fransiyadagi diniy urushlar davrida","Angliyadagi sanoat inqilobi yillarida","Yaponiyada XX asr oxirlarida"],e:"Uni janublik sobiq askarlar 1861–1865-yillardagi urushdan so‘ng tuzgan."},
 {t:"m",q:"Islamofobiya tushunchasi darslikka ko‘ra nima oqibatida yuzaga keldi?",a:["OAVda «terrorizm» va «islom» so‘zlari birga ishlatilishi","Musulmon davlatlarida sayyohlik keskin kamayib ketishi","Diniy kitoblarning ko‘p tillarga tarjima qilinishi","Dinlararo anjumanlarning tez-tez o‘tkazilishi"],e:"Bu so‘zlarning ko‘p hollarda yonma-yon ishlatilishi qo‘rquv tug‘dirgan."},
 {t:"m",q:"«Diniy kamsitish» nima?",a:["Diniy mansubligiga ko‘ra huquqlarni cheklash","Diniy bayramlarni birgalikda nishonlash","Diniy manbalarni ilmiy jihatdan o‘rganish","Turli din vakillarining o‘zaro hamkorligi"],e:"Kishilar haq-huquqini dinga qarab chegaralash — diniy diskriminatsiya."},
 {t:"m",q:"Yahudiylik diniga nisbatan salbiy munosabat qanday ataladi?",a:["Yudofobiya","Xristianofobiya","Islamofobiya","Ksenomaniya"],e:"Xristianlikka nisbatan — xristianofobiya, yahudiylikka — yudofobiya."},
 {t:"m",q:"Jangari voqeasida oila boshlig‘i nega «u Qur’onni bilmaydi» dedi?",a:["Qur’onni bilgan odam jangari bo‘lmas edi","Jangari chet tilida umuman gaplashmasdi","Uni avvaldan yaqindan tanir va bilardi","Jangari Injilni yoddan bilishini sezgandi"],e:"U haqiqiy dinni bilgan kishi zo‘ravonlik yo‘liga kirmasligini bildirdi."},
 {t:"m",q:"Irqiy kamsitishni tugatish konvensiyasi qaysi yili qabul qilingan?",a:["1965-yilda","1948-yilda","1995-yilda","2020-yilda"],e:"1965-yil 21-dekabrda qabul qilinib, 1969-yilda kuchga kirgan."},
 {t:"m",q:"Konvensiya bajarilishi ustidan monitoringni qaysi organ olib boradi?",a:["BMTning irqiy kamsitishni tugatish qo‘mitasi","YUNESKOning madaniy merosni asrash qo‘mitasi","Xalqaro olimpiya qo‘mitasining ijroiya organi","Jahon sog‘liqni saqlash tashkiloti kengashi"],e:"Darslik ma’lumotiga ko‘ra, nazorat BMT qo‘mitasida."},
 {t:"tf",q:"Darslikka ko‘ra, ekstremistlar xunrezligini «islomning shartlari» deb talqin qilib bo‘lmaydi.",a:true,e:"Bunday guruhlar manbalarni buzib talqin qiladi, ularni din bilan bog‘lash noto‘g‘ri."},
 {t:"tf",q:"O‘zbekiston Irqiy kamsitishni tugatish konvensiyasiga 1995-yilda qo‘shilgan.",a:true,e:"1995-yil 31-avgustda qo‘shilgan, 28-oktabrdan kuchga kirgan."},
 {t:"tf",q:"XXI asrda odamlarda yangilikdan qo‘rqish hissi butunlay yo‘qoldi.",a:false,e:"Qo‘rquv yo‘qolmadi, faqat uning obyekti o‘zgardi."},
 {t:"f",q:"Ksenofobiyani yengish uchun nima qilish kerak? Ikki-uch taklif bering.",e:"Begona narsani bilib o‘rganish, ishonchli manbalardan foydalanish, muloqot va bag‘rikenglik, kamsitishga yo‘l qo‘ymaslik."}]},

{id:"m8",n:"10–11-mavzu",t:"Missionerlik – yoshlar kelajagiga tahdid",b:2,
 map:{c:"Missionerlik – yoshlar kelajagiga tahdid",br:[
  {t:"Tushunchalar",e:"🎯",k:["missionerlik","prozelitizm","majburan singdirish"],x:"Missionerlik — odamni o‘z diniga kiritish uchun mafkuraviy ta’sir; prozelitizm — boshqa konfessiyaga o‘tkazishga qaratilgan shakli."},
  {t:"«10/40 oyna»",e:"🗺️",k:["parallellar","resurslar","mojarolar"],x:"Missionerlar e’tibori boy resursli, aholisi asosan islom, budda, hind va konfutsiy dinidagi hududga qaratilgan."},
  {t:"Usullar",e:"🎁",k:["bepul kurslar","xayriya","tibbiy yordam"],x:"Til kurslari, xorijga jo‘natish, oromgoh, sovg‘a va yordam bahonasida targ‘ibot qilinadi."},
  {t:"Oqibatlar",e:"💔",k:["oila buzilishi","sektalar","o‘z joniga qasd"],x:"Hikoyalarda ayol farzandlarini ovqat va doridan mahrum qiladi; sektalar yuzlab odam o‘limiga sabab bo‘lgan."},
  {t:"Himoya",e:"🛡️",k:["qonun","tahlil qilish","ma’rifat"],x:"Axborotni tahlil qilish va «jaholatga qarshi ma’rifat» tamoyili himoya vositasi."}]},
 q:[
 {t:"m",q:"Prozelitizm nima?",a:["Dindorlarni boshqa konfessiyaga o‘tkazishga urinish","Barcha dinlarni teng hurmat qilishga chaqiruvchi faoliyat","Diniy yodgorliklarni ta’mirlashga qaratilgan faoliyat","Dinshunoslik bo‘yicha ilmiy tadqiqot olib borish"],e:"U missionerlikning bir konfessiyadagilarni boshqasiga o‘tkazishga qaratilgan shakli."},
 {t:"m",q:"«10/40 oyna» deb nimaga aytiladi?",a:["Missionerlar e’tiboridagi parallellar oralig‘i","Sektalar yig‘iladigan maxsus bino derazasi","O‘qishga qabul qilish bo‘yicha yosh chegarasi","Diniy adabiyotlar uchun bojxona me’yori"],e:"10- va 40-parallellar orasidagi hudud."},
 {t:"m",q:"«10/40 oyna» hududining ahamiyati nimada deb ko‘rsatilgan?",a:["Yirik gaz, neft, uran zaxiralari va strategik yo‘llar borligida","Aholisi juda kam va yer osti boyliklari mutlaqo yo‘qligida","Faqat sayyohlik uchun qulay sovuq iqlimi mavjudligida","Dunyodagi eng yirik muzliklar shu yerda joylashganida"],e:"Hududda resurslar, transport yo‘llari, bo‘g‘oz va ko‘rfazlar bor."},
 {t:"m",q:"Qonunga ko‘ra, diniy e’tiqodni sabab qilib nima qilish mumkin emas?",a:["Qonuniy majburiyatdan bo‘yin tovlash","Ibodatxonaga borib ibodat qilish","Diniy bayramni oilada nishonlash","Muqaddas kitobni o‘qib o‘rganish"],e:"«Vijdon erkinligi...» qonunining 6-moddasidan."},
 {t:"m",q:"Krasnodar o‘lkasidan yozilgan maktubda ayolni nima o‘ziga tortgan edi?",a:["«Vissarion ota» videoma’ruzalari","Xorijiy tilni o‘rgatuvchi bepul kurs","Gazetadagi ishga taklif e’loni","Yozgi oromgohdagi uchrashuvlar"],e:"O‘zini Masih deb atagan kimsaning ma’ruzalaridan so‘ng ayol o‘zgarib qoldi."},
 {t:"m",q:"Maktub muallifi o‘quvchilarni nimaga chaqiradi?",a:["Axborotni doimo tahlil qilishga","Internetdan butunlay voz kechishga","Har qanday da’vatga ishonishga","Shifokorlarga murojaat qilmaslikka"],e:"U ommaviy axborot va internetdagi ma’lumotni tahlil qilishni so‘raydi."},
 {t:"m",q:"«Arosat» hikoyasida O‘rmonxon kimlarni pul bilan avrash oson deb biladi?",a:["Yordamga muhtoj, qiynalgan odamlarni","Boy va obro‘li tadbirkor kishilarni","Dinshunos olimlar va imomlarni","Qonunni puxta biladigan fuqarolarni"],e:"U muhtojlar va e’tiqodi zaif yoshlarga e’tibor berishni buyuradi."},
 {t:"m",q:"Qaysi biri darslikda missionerlar usuli sifatida sanalgan?",a:["Til va kompyuter kursi bahonasida targ‘ib qilish","Davlat maktablarida tarix fanidan imtihon olish","Mahalla hasharida chiqindi yig‘ishtirib ketish","Kutubxonaga milliy adabiyot sovg‘a qilish"],e:"Ingliz, koreys tili yoki kompyuter o‘rgatish bahonasida kurslar ochiladi."},
 {t:"tf",q:"Sekta faqat o‘z e’tiqodini «haq din» deb da’vo qilib, aslida siyosiy va iqtisodiy maqsadni ko‘zlashi mumkin.",a:true,e:"Darslikda sekta shunday guruh sifatida tasvirlanadi."},
 {t:"tf",q:"1970–2000-yillarda xorijiy missiyalarga sarflangan mablag‘ kamaygan.",a:false,e:"Mablag‘ 3 milliard dollardan 12 milliardga oshgan."},
 {t:"tf",q:"Matluba hikoyasida u ota-onasining so‘zi bilan darhol yo‘lidan qaytdi.",a:false,e:"U qaytmadi, hatto ota-onasini ham qo‘shilishga chaqirdi."},
 {t:"f",q:"Missionerlar ta’siriga tushib qolmaslik uchun o‘zingiz va yaqinlaringizga qanday maslahat berasiz?",e:"Shubhali yordam va kurslarni tekshirish, axborotni tahlil qilish, diniy bilimni ishonchli manbadan olish, kattalar va mas’ullar bilan maslahatlashish."}]},

{id:"m9",n:"12–13-mavzu",t:"Kibermakonda axborot iste’moli madaniyati",b:2,
 map:{c:"Kibermakonda axborot iste’moli madaniyati",br:[
  {t:"Axborot",e:"📡",k:["sezgi a’zolari","tarmoqlar","kino"],x:"Axborot turli shaklda uzatiladi; kinematografiya eng intensiv usulga aylangan va dunyoqarashga ta’sir qiladi."},
  {t:"Yashirin ta’sir",e:"🎬",k:["seriallar","multfilmlar","begona g‘oyalar"],x:"Film va seriallar orqali g‘oyalar ochiq yoki yashirin singdirilishi mumkin."},
  {t:"Internet tuzoqlari",e:"🌐",k:["virtual do‘stlar","jangari videolar","yolg‘on da’vat"],x:"«Tagi puch gaplar» va «Men zulmatdan nur izlabman» hikoyalari ogohlantiradi."},
  {t:"Kiberxavf",e:"💻",k:["bank-troyanlari","virusli ilovalar","kibernetika"],x:"Mobil qurilmalarga virusli ilovalar zarar yetkazadi."},
  {t:"Iste’mol madaniyati",e:"🧠",k:["saralash","hayo","mafkuraviy immunitet"],x:"Axborotni foydali va foydasizga ajratish, har narsaning foydasi va zararini ko‘rish kerak."}]},
 q:[
 {t:"m",q:"Darslikka ko‘ra, ma’lumot uzatishning eng intensiv usuliga nima aylandi?",a:["Kinematografiya","Bosma gazeta","Devoriy e’lon","Og‘zaki suhbat"],e:"Kino ma’lumot uzatibgina qolmay, dunyoqarashni ham shakllantiradi."},
 {t:"m",q:"Aziz ukalarining multfilm asosidagi janjalini ko‘rib nima qildi?",a:["Televizorni o‘chirib, ertak o‘ynashni taqiqladi","Ular bilan birga yangi foydali o‘yin boshladi","Ota-onasiga qo‘ng‘iroq qilib maslahat so‘radi","E’tibor bermay kompyuterda o‘ynayverdi"],e:"Ammo keyin ukalarini nima bilan band qilishni bilmay qoldi."},
 {t:"m",q:"«Axborot urushi» iborasini ilk bor kim qo‘llagan?",a:["Fizik olim Tomas Ron","Yozuvchi Lev Tolstoy","Siyosatchi Alfred Mexen","Olim Masaru Emoto"],e:"Tomas Ron 1976-yilda bu masalaga mas’ullar e’tiborini qaratgan."},
 {t:"m",q:"Yunoncha «kibernetika» so‘zi nimani bildiradi?",a:["Boshqarish san’ati","Hisoblash ilmi","Aloqa vositasi","Sirli yozuv"],e:"Kibernetika axborotni qabul qilish, qayta ishlash va boshqarishda qo‘llash bilan shug‘ullanadi."},
 {t:"m",q:"«Tagi puch gaplar» hikoyasi qahramoni nimani kech anglab yetdi?",a:["«Birodarlar» tushuntirgani asl islomdan uzoq ekanini","Moskvada ish topish umuman mumkin emasligini","Fleshka va telefonining butunlay buzilganini","Oilasi undan avvalroq bu guruhga qo‘shilganini"],e:"Internetda topganlari quruq sarob va buzg‘unchi ma’lumot ekan."},
 {t:"m",q:"«Zulmatdan nur izlabman» hikoyasida qahramon telefoniga qanday xabar kelgan?",a:["«Hijrat qilishingiz kerak»","«Sizga mukofot ajratildi»","«Kursga yozilishga shoshiling»","«Qarzingizni tez to‘lang»"],e:"Shu xabardan so‘ng u tushuntiruvchilar ta’siriga tushib qoldi."},
 {t:"m",q:"«Har qanday narsaga har tomonlama nazar sol – foydasini ham, zararini ham ko‘r» fikri nimaga o‘rgatadi?",a:["Axborotni tanqidiy baholashga","Har xabarni darhol tarqatishga","Yangilikdan butunlay qochishga","Faqat boshqalar fikriga tayanishga"],e:"Ma’lumotni qabul qilishdan oldin foyda va zararini tahlil qilish kerak."},
 {t:"m",q:"Vazirlar Mahkamasining 2014-yilgi 10-son qarori bilan tasdiqlangan nizom nimani tartibga soladi?",a:["Diniy materiallarni tayyorlash va tarqatishni","Maktablarda kompyuter sinflari tashkil etishni","Telekanallarning reklama vaqtini belgilashni","Mobil aloqa tariflarini hisoblab chiqishni"],e:"Diniy mazmundagi materiallarni tayyorlash, olib kirish va tarqatish tartibi."},
 {t:"tf",q:"Darslikda keltirilgan hadisga ko‘ra, hayo va iymon bir-biriga yaqin: biri yo‘qolsa, ikkinchisi ham yo‘qoladi.",a:true,e:"Bu fikr «Ma’naviyat xazinasi» ruknida berilgan."},
 {t:"tf",q:"Hikoyadagi «Gumroh» o‘z ishlari uchun hech qanday javobgarlikka tortilmagan.",a:false,e:"U qora kursida o‘tirib, qilmishlarini sarhisob qilmoqda."},
 {t:"tf",q:"Seriallar va multfilmlardagi axborot bolalarning hayot tarziga ta’sir etishi mumkin.",a:true,e:"Odobga zid odatlar ularning hayot tarziga aylanib qolishi mumkin."},
 {t:"f",q:"Internetda notanish kishidan shubhali da’vat kelsa, qanday yo‘l tutasiz? Nima uchun?",e:"Javob bermaslik va bloklash, havolalarni ochmaslik, kattalarga yoki tegishli organga xabar berish, ma’lumotni rasmiy manbadan tekshirish."}]},

{id:"m10",n:"14–15-mavzu",t:"Dunyo dinlarida tinchlik g‘oyasi",b:2,
 map:{c:"Dunyo dinlarida tinchlik g‘oyasi",br:[
  {t:"Umumiy g‘oya",e:"☮️",k:["tinchlik","insonparvarlik","urushga qarshi"],x:"Hech qaysi din nohaq qon to‘kish, urush va buzg‘unchilikni targ‘ib qilmaydi."},
  {t:"Budda va Iso ta’limoti",e:"🛐",k:["tirik jonga ozor bermaslik","yaxshilik","ezgulik"],x:"Buddaviylik va xristianlik yomonlik qilmaslikka chaqiradi."},
  {t:"Islom va sulh",e:"🤝",k:["Hudaybiya","firqalarga bo‘linmaslik","Najron maktubi"],x:"628-yilgi sulh tinchlikni ta’minladi; Payg‘ambar maktubi nasroniylarga ibodat erkinligini kafolatlagan."},
  {t:"Niqoblangan zo‘ravonlik",e:"⚔️",k:["qarmatiylar","Varfolomey kechasi","Aum Sinrikyo"],x:"Din niqobidagi ekstremizm ko‘p qurbonlarga sabab bo‘lgan."},
  {t:"Vijdon erkinligi",e:"⚖️",k:["dunyoviy davlat","teng sharoit","qonun"],x:"Davlat diniy qarashni majburan singdirishga yo‘l qo‘ymaydi, konfessiyalar totuvligini mustahkamlaydi."}]},
 q:[
 {t:"m",q:"Haqiqiy buddaviy amal qiladigan beshta shartning birinchisi qaysi?",a:["Tirik jonga zarar yetkazmaslik","Yiliga bir marta safarga chiqish","Boylikning yarmini ibodatxonaga berish","Faqat tunda ovqatlanish"],e:"Shu bois budda rohiblari chivinni ham asrashga harakat qilgan."},
 {t:"m",q:"1995-yilda Tokio metrosida terror sodir etgan sekta qaysi?",a:["«Aum Sinrikyo»","«Osmon darvozasi»","«Dovud avlodi»","«Xalq ibodatxonasi»"],e:"Buddaviylikdan ajralib chiqqan sekta; 12 kishi halok bo‘lgan."},
 {t:"m",q:"Dunyoda eng keng tarqalgan jahon dini deb qaysi biri ko‘rsatilgan?",a:["Xristianlik","Buddaviylik","Konfutsiylik","Hinduiylik"],e:"Darslikda xristianlik eng keng tarqalgan jahon dini deyiladi."},
 {t:"m",q:"Hudaybiya sulhi qaysi yili imzolangan?",a:["Milodiy 628-yilda","Milodiy 570-yilda","Milodiy 899-yilda","Milodiy 930-yilda"],e:"Sulh qabilalar daxlsizligi va tinchligini ta’minlagan."},
 {t:"m",q:"Hudaybiya sulhi natijalaridan biri qaysi?",a:["Har ikki tomon asirlari ozod qilindi","Savdo aloqalari butunlay to‘xtatildi","Qabilalar o‘rtasida urush avj oldi","Ibodatxonalar yopib qo‘yildi"],e:"Asirlar ozod etildi, savdo aloqalari mustahkamlandi."},
 {t:"m",q:"«Varfolomey kechasi» qaysi mamlakatda yuz bergan?",a:["Fransiyada","Italiyada","Bahraynda","Yaponiyada"],e:"1572-yilda protestantlar qirg‘in qilindi va uzoq diniy urush boshlandi."},
 {t:"m",q:"Bobur Humoyunga vasiyatida turli mazhablarga qanday qarashni buyurgan?",a:["Pok qalb va adolat bilan","Shubha va qattiqqo‘llik bilan","Befarqlik va masofa bilan","Zulm tig‘i bilan tazyiq qilib"],e:"«Har bir mazhabga pok qalb bilan qaragin... adolatli bo‘lgin»."},
 {t:"m",q:"2019-yilda Kraystcherchdagi masjidlarda yuz bergan terror nimaning avj olishi natijasi edi?",a:["Ksenofobiya va islamofobiyaning","Iqtisodiy inqiroz va ishsizlikning","Ekologik muammolar kuchayishining","Savdo raqobati keskinlashuvining"],e:"Yangi Zelandiyadagi hujum 51 dan ortiq kishi hayotiga zomin bo‘ldi."},
 {t:"tf",q:"Darslikka ko‘ra, dunyoviylik — dahriylik degani emas.",a:true,e:"Karimov fikricha, dinni butunlay rad etish xalq qadriyatlarini ham rad etadi."},
 {t:"tf",q:"Zamonaviy qurol-yarog‘ga ega bo‘lishning o‘zi tinchlikni to‘liq ta’minlaydi.",a:false,e:"Buzg‘unchi kuchlar yashirin usullarni qo‘llaydi, qurolning o‘zi yetarli emas."},
 {t:"tf",q:"Fuqarolik va siyosiy huquqlar paktiga ko‘ra, urushni targ‘ib qilish qonun bilan taqiqlanishi kerak.",a:true,e:"20-moddada urush va adovat targ‘ibini taqiqlash belgilangan."},
 {t:"f",q:"«Din terror emas, terror din emas» degan fikrni o‘z so‘zlaringiz bilan izohlang.",e:"Dinlar tinchlik va ezgulikka chaqiradi; terrorchilar dinni niqob qiladi, ularning qilmishi din ta’limotiga zid."}]},

{id:"m11",n:"16–17-mavzu",t:"Tuyg‘ularning xilmaxilligi",b:3,
 map:{c:"Tuyg‘ularning xilmaxilligi",br:[
  {t:"O‘spirinlik",e:"🌱",k:["nozik davr","orzu va hadik","iroda"],x:"Katta hayot bo‘sag‘asida qat’iylik, shijoat, andisha, oriyat va ijodkorlik zarur."},
  {t:"Nozik tuyg‘ular",e:"💞",k:["muhabbat","sadoqat","vafo"],x:"Do‘stlik, ishonch, muhabbat, sadoqat va vafo — insonga xos nozik tuyg‘ular."},
  {t:"Ona mehri",e:"👩‍👦",k:["Ronaldu","minnatdorlik","g‘amxo‘rlik"],x:"Ronaldu muvaffaqiyatlarini o‘zi uchun mehnat qilgan onasiga bag‘ishlaydi."},
  {t:"Sarishtalik rivoyati",e:"🧹",k:["supurindi sinovi","rostgo‘ylik","kelin"],x:"Uyidan eng oz supurindi chiqargan qiz soddaligi va halolligi bilan podshohga yoqdi."},
  {t:"Hamdardlik va do‘st",e:"📖",k:["Kibriyo Qahhorova","do‘st tanlash","maslahat"],x:"Qahhorlar hayoti — samimiy tuyg‘u namunasi; ahmoq, baxil, yolg‘onchi bilan do‘stlashmaslik tavsiya etiladi."}]},
 q:[
 {t:"m",q:"Ronaldu onasi uchun nega alohida uy olib bermasligini qanday tushuntirdi?",a:["Onasi o‘zidan kechib katta qilgani uchun doim yonida bo‘lishini aytdi","Hozircha yangi uy olishga mablag‘i yetmayotganini aytdi","Onasi boshqa shaharda yashashni afzal ko‘rishini aytdi","Mashg‘ulotlari ko‘pligi sababli vaqt topa olmayotganini aytdi"],e:"U onasining mehnatini eslab, u tirik ekan yonida bo‘lishini aytgan."},
 {t:"m",q:"Anvar Ra’noga munosabati haqida kimdan maslahat olishga qaror qildi?",a:["Onasidan","Sinfdoshidan","Mahalla faolidan","Notanish blogerdan"],e:"U onasi eng to‘g‘ri maslahat berishiga ishonadi."},
 {t:"m",q:"Anvar o‘zining sha’ni bilan birga yana nimani asrash zarur deb o‘yladi?",a:["Ra’noning sha’ni va obro‘sini","O‘z maktabining reytingini","Do‘stlarining kayfiyatini","Cho‘ntagidagi jamg‘armasini"],e:"«Ra’noning ham sha’ni, obro‘sini asrashim kerak»."},
 {t:"m",q:"Go‘zalning buvisi qiz bolani nimaga o‘xshatgan?",a:["Sirli sandiqqa","Ochiq kitobga","Tiniq oynaga","Tez daryoga"],e:"His-tuyg‘ularini har kimga bildirmaslik haqidagi o‘git."},
 {t:"m",q:"Supurindi rivoyatida qizning qaysi xislatlari podshohga yoqdi?",a:["Soddaligi, saranjomligi, rostgo‘yligi va halolligi","Boyligi, taqinchoqlari va qimmatbaho liboslari","Ayyorligi, epchilligi va maqtana olish mahorati","Nasl-nasabi, mansabi va tanishlarining ko‘pligi"],e:"Podshoh bu fazilatlarga tasanno aytib, uni kelin qildi."},
 {t:"m",q:"Ali ibn Abu Tolib nasihatida ahmoqni do‘st tutish nega xavfli?",a:["Foyda beraman deb zarar yetkazadi","Uzoqni yaqin qilib ko‘rsatib aldaydi","Eng muhtoj paytda narsasini qizg‘anadi","Sirlaringizni hech qachon eshitmaydi"],e:"Ahmoq foyda bermoqchi bo‘lib zarar qiladi."},
 {t:"m",q:"Shu nasihatda yolg‘onchi nimaga o‘xshatilgan?",a:["Sarobga","Bo‘ronga","Tikanga","Soyaga"],e:"U uzoqni yaqin, yaqinni uzoq qilib ko‘rsatadi."},
 {t:"m",q:"«100 kun ichida shaxsiyatni o‘stirish» mashqlaridan biri qaysi?",a:["«Tonggi sahifalar» daftarini yuritish","Har kuni kechgacha serial tomosha qilish","Faqat tanish mavzularni takrorlash","Yangi odamlardan butunlay qochish"],e:"Tongda kelgan fikrlarni maxsus daftarga yozish tavsiya etiladi."},
 {t:"tf",q:"Abdulla Qahhor rafiqasi Kibriyoxonimga qattiq bog‘lanib qolgan edi.",a:true,e:"Xurshid Davron yozishicha, u rafiqasisiz o‘zini qo‘yarga joy topolmasdi."},
 {t:"tf",q:"100 kunlik mashqlarda shukronalik uyg‘otadigan narsalarni yozib borish tavsiya etiladi.",a:true,e:"Har kuni mamnun qiladigan 5–10 narsani qayd etish tavsiya qilinadi."},
 {t:"tf",q:"Ali ibn Abu Tolib baxil bilan do‘stlashishni tavsiya qiladi.",a:false,e:"Aksincha, undan saqlanishni uqtiradi: u eng kerakli narsani sendan uzoq qiladi."},
 {t:"f",q:"Haqiqiy do‘stlikda qaysi tuyg‘u va fazilatlar muhim? Fikringizni misol bilan yozing.",e:"Ishonch, sadoqat, vafo, hurmat, rostgo‘ylik; do‘st qiyin paytda yonda turadi va to‘g‘ri yo‘lga undaydi."}]},

{id:"m12",n:"18-mavzu",t:"Nafosat va ma’naviyat",b:3,
 map:{c:"Nafosat va ma’naviyat",br:[
  {t:"Nafosat tushunchasi",e:"🌸",k:["go‘zallik","mukammallik","mutanosiblik"],x:"Nafosat — narsa va hodisalar ko‘rinishidagi mukammallik, mutanosiblik; inson aqli, ko‘rinishi, nutqi va fazilatlari uyg‘unligi."},
  {t:"Haqiqiy va soxta",e:"✨",k:["ichki dunyo","tabiiy go‘zallik","ijtimoiy mazmun"],x:"Yuksak fazilat va xalqchil g‘oyani jamlagan nafosatgina haqiqiy."},
  {t:"Muloqot madaniyati",e:"💬",k:["xushmuomalalik","shirinso‘zlik","andisha"],x:"So‘zlashuv madaniyati shaxs xulqi go‘zalligini aks ettiradi."},
  {t:"Ma’ruza san’ati",e:"🎤",k:["aniq g‘oya","vizual aloqa","ishonch"],x:"Notiq sodda va ravon gapiradi, tinglovchi bilan ko‘z orqali aloqa qiladi."},
  {t:"Qalam ta’rifi",e:"🖋️",k:["«Hayrat ul-abror»","Navoiy","so‘z san’ati"],x:"Navoiy qalamni qush, ilon, ajdar va hassaga o‘xshatib, nafis tasvirlaydi."}]},
 q:[
 {t:"m",q:"Insonning aqli, tashqi ko‘rinishi, nutqi va ezgu fazilatlari uyg‘unlashuvi nima deb ataladi?",a:["Nafosat","Etiket","Imij","Daxldorlik"],e:"Darslik nafosatni shunday uyg‘unlik sifatida izohlaydi."},
 {t:"m",q:"Qanday nafosatgina haqiqiy hisoblanadi?",a:["Insoniy fazilat va tabiiy go‘zallikni jamlagan","Faqat qimmat kiyim va bezakka asoslangan","Boshqalarga taqlid qilib yasalgan nafislik","Tashqi shakli uchungina e’tibor tortadigan"],e:"Haqiqiy nafosatda fazilat, xalqchil g‘oya, ijtimoiy mazmun va tabiiy go‘zallik bor."},
 {t:"m",q:"Insonning go‘zal bo‘lishida tashqi ko‘rinishdan tashqari nima muhim?",a:["Ichki dunyosi va axloqiy fazilatlari","Ijtimoiy tarmoqdagi obunachilari soni","Kiyimlarining narxi va ishlab chiqaruvchisi","Yaqinlarining mansabi va boyligi"],e:"Ma’naviy-axloqiy fazilatlar ham muhim o‘rin tutadi."},
 {t:"m",q:"Navoiyning «Hayrat ul-abror»dan olingan parchasida nima ta’riflanadi?",a:["Qalam","Soat","Ko‘zgu","Chiroq"],e:"Qush, ilon, ajdar va hassaga qiyos qilingan narsa — qalam."},
 {t:"m",q:"Ommaviy chiqishda ma’ruzani qanday uslubda olib borish tavsiya etiladi?",a:["Samimiy so‘zlashuv va muloqot uslubida","Matnni boshini ko‘tarmay o‘qish uslubida","Uzun va murakkab jumlali monologda","Kuchli hayajon bilan baqirib gapirishda"],e:"Monolog emas, ochiq muloqot uslubi tavsiya qilinadi."},
 {t:"m",q:"Ma’ruza matnini kim tayyorlashi shart?",a:["Notiqning shaxsan o‘zi","Notiqning rahbari","Tinglovchilar guruhi","Tasodifiy yordamchi"],e:"Notiq matnni o‘zi tayyorlab, asosiy tezislarni yod oladi."},
 {t:"m",q:"Nutq paytida qaysi harakat odatda yolg‘on gapirayotganda uchrashi sababli tavsiya etilmaydi?",a:["Dam-badam yuzga qo‘l tekkizish","Tinglovchilarga qarab gapirish","Qaddini tik tutib turish","Jumlalarni lo‘nda aytish"],e:"Qo‘l bilan yuzga tez-tez tegish ishonchsizlik uyg‘otadi."},
 {t:"m",q:"Muloqot madaniyatining axloqiy me’yorlari qatoriga nima kiradi?",a:["Xushfe’llik va shirinso‘zlik","Takabburlik va kesatish","So‘zni bo‘lish va baqirish","Loqaydlik va qo‘pollik"],e:"Xushmuomalalik, shirinso‘zlik, ochiqko‘ngillik va muloyimlik."},
 {t:"tf",q:"Darslik tavsiyasiga ko‘ra, notiq o‘zini oqlab, qayta-qayta kechirim so‘rashi obro‘sini oshiradi.",a:false,e:"Bu tinglovchilarga ruhiy ustunlik berib, notiq nufuzini tushiradi."},
 {t:"tf",q:"Nafosat madaniyati insonning jamiyatdagi faolligi va boshqalar bilan munosabatiga ham bog‘liq.",a:true,e:"Moddiy va madaniy merosni o‘zlashtirish ham ta’sir qiladi."},
 {t:"tf",q:"Ma’ruzada bosh g‘oya iloji boricha mavhum va murakkab tilda berilishi kerak.",a:false,e:"Bosh g‘oya ochiq, sodda va ravon bayon qilinadi."},
 {t:"f",q:"Nafosat va ma’naviyat qanday bog‘liq? O‘zingiz bilgan misol bilan tushuntiring.",e:"Tashqi go‘zallik ichki fazilatlar bilan uyg‘unlashsa haqiqiy bo‘ladi: shirin so‘z, odob, orastalik, hunarmandning didli ishi."}]},

{id:"m13",n:"19–20-mavzu",t:"Surat va siyrat",b:3,
 map:{c:"Surat va siyrat",br:[
  {t:"Imij",e:"🪪",k:["qiyofa","ta’sir","image"],x:"Imij — odamlarga hissiy-ruhiy ta’sir ko‘rsatish uchun shakllantiriladigan qiyofa."},
  {t:"Jamoa imiji",e:"🏢",k:["har bir a’zo","o‘quv-seminar","brend"],x:"Jamoa imijini yaratish har bir a’zo zimmasida; tashkilotga ham brend kerak."},
  {t:"Erkaklar libosi",e:"👔",k:["galstuk","pidjak","ko‘ylak manjeti"],x:"Rasmiy libosda ranglar mosligi, dazmol va ixchamlik muhim."},
  {t:"Ayollar libosi",e:"👗",k:["maqbul uzunlik","kamtar pardoz","oz taqinchoq"],x:"Eng asosiysi — kiyim qomatga yarashishi, qulay va ozoda bo‘lishi."},
  {t:"Submadaniyat",e:"⚠️",k:["ommaviy madaniyat","gotlar","hayo"],x:"«Ommaviy madaniyat» tahdidlaridan ogoh bo‘lish; kiyinish ichki dunyoni aks ettiradi."}]},
 q:[
 {t:"m",q:"Inglizcha «image» so‘zi qaysi ma’noni anglatadi?",a:["Qiyofa, ko‘rinish, timsol","Tartib, qoida, intizom","Nutq, so‘zlash mahorati","Obro‘li lavozim, mansab"],e:"«Image» — ko‘rinish, qiyofa, siymo, timsol."},
 {t:"m",q:"«Asling kabi ko‘rin yoki ko‘ringaning kabi bo‘l» degan so‘z kimniki?",a:["Jaloliddin Rumiy","F. Shalyapin","Mahmud Zamaxshariy","Zahiriddin Bobur"],e:"Rumiy surat va siyrat birligiga chaqiradi."},
 {t:"m",q:"«Dress-kod» atamasi qanday ma’noni bildiradi?",a:["Libos kodeksi","Nutq madaniyati","Salomlashish tartibi","Mahsulot belgisi"],e:"Inglizchadan olingan atama — kiyinish qoidalari."},
 {t:"m",q:"Jamoa imijini yaratish vazifasi kimga yuklatiladi?",a:["Jamoaning har bir a’zosiga","Faqat tashkilot rahbariga","Faqat reklama mutaxassisiga","Tashrif buyuruvchi mijozga"],e:"Har bir a’zo imij shakllanishida mas’ul."},
 {t:"m",q:"Ayollar uchun ish kiyimida taqinchoqlar haqida qanday tavsiya bor?",a:["Yirik, yaltiroq bo‘lmasin, uchtadan oshmasin","Imkon qadar yirik va yaltiroq bo‘lib ko‘rinsin","Kamida besh xil bezak birga taqib yurilsin","Faqat oltindan va ko‘p qatorli bo‘lsin"],e:"Zirak, uzuk va zanjir — uchtadan ortmasligi lozim."},
 {t:"m",q:"Qishda qanday galstuk taqqan ma’qul?",a:["Qoramtir to‘q rangli","Juda yorqin tusli","Ko‘p rasmli, yaltiroq","Faqat oppoq rangli"],e:"Qishda to‘q, yozda yorqin tusdagi galstuk tavsiya etiladi."},
 {t:"m",q:"Boburning «Boburnoma»dagi ta’rifiga ko‘ra, Alisherbek ahli fazl va hunarga qanday munosabatda bo‘lgan?",a:["Misli kam homiy va murabbiy bo‘lgan","Ularning ishiga befarq qaragan","Faqat shoirlarni qo‘llab, boshqani rad etgan","Musiqa va tasvir san’atidan uzoq yurgan"],e:"U Behzod, Shoh Muzaffar va sozandalar kamoliga ko‘maklashgan."},
 {t:"m",q:"Gotlar submadaniyatining darslikda aytilgan asosiy g‘oyasi qaysi?",a:["O‘limni romantiklashtirish va iztirobdan lazzatlanish","Sog‘lom turmush va sportni keng targ‘ib qilish","Milliy kiyim va an’analarni qayta tiklash","Ilm-fan yutuqlarini ommaga yetkazish"],e:"Bu «ommaviy madaniyat» bilan bog‘liq xatarli ko‘rinish sifatida tanqid qilingan."},
 {t:"tf",q:"Mahmud Zamaxshariyga ko‘ra, husni xulqi yo‘q kishini hech qanday kiyim ko‘rkam qila olmaydi.",a:true,e:"Ichki go‘zallik tashqi libosdan ustun."},
 {t:"tf",q:"Pidjakning tashqi cho‘ntaklariga ruchka va taroqni ko‘rinadigan qilib solib yurish tavsiya etiladi.",a:false,e:"Bunday qilish tavsiya etilmaydi."},
 {t:"tf",q:"Imij faqat insonlarga kerak, tashkilotlarga uning ahamiyati yo‘q.",a:false,e:"Tashkilot va firmalar ham bozorda o‘rin olish uchun o‘z imijiga muhtoj."},
 {t:"f",q:"«Mening imijim» mavzusida: odamlar sizni qanday tanishini xohlaysiz va buning uchun nima qilasiz?",e:"Bilimli, odobli, ozoda ko‘rinish; muomala va nutq ustida ishlash; so‘z va ish birligi, aslidek ko‘rinish."}]},

{id:"m14",n:"21–22-mavzu",t:"Etiket",b:3,
 map:{c:"Etiket",br:[
  {t:"Mohiyat",e:"📏",k:["o‘zini tutish","muloqot","subordinatsiya"],x:"Etiket — o‘zini tutish qoidalari; muloqot elementlari: salomlashish, tanishuv, murojaat, subordinatsiya."},
  {t:"Salomlashish",e:"👋",k:["tabassum","qo‘l berish","kattaga hurmat"],x:"Kichiklar kattalarga salom beradi, qo‘lni qattiq qismaslik kerak."},
  {t:"Tanishtirish",e:"🤵",k:["mezbon","qisqa ma’lumot","davra"],x:"Mezbon yangi mehmonni tanishtiradi, odamlar haqida qisqa ma’lumot beriladi."},
  {t:"Jamoat joyi",e:"🚌",k:["eskalator","transport","past ovoz"],x:"Eskalatorda o‘ngda turiladi; baland ovoz va qattiq kulish odobsizlik."},
  {t:"Dasturxon odobi",e:"🍽️",k:["o‘z oldidan olish","bo‘lib ichish","chapillatmaslik"],x:"Suvni uch bo‘lib ichish, taomni o‘z oldidan olish odobdandir."}]},
 q:[
 {t:"m",q:"Quyidagilarning qaysi biri samarali muloqotning asosiy elementlaridan?",a:["Subordinatsiya","Improvizatsiya","Konfrontatsiya","Manipulyatsiya"],e:"Elementlar: salomlashish, tanishuv, murojaat, subordinatsiya."},
 {t:"m",q:"Erkaklar va ayollar tanishtirilganda qaysi tartib to‘g‘ri?",a:["Erkaklar ayollarga tanishtiriladi","Ayollar doim oxirida eslatiladi","Faqat erkaklar o‘zaro tanishadi","Kattalar tanishtirilmasdan qoladi"],e:"Avvalo erkaklar ayollar bilan tanishtiriladi."},
 {t:"m",q:"Transport vositasidan tushishda etiket nimani talab qiladi?",a:["Oldin erkak kishi tushishi kerak","Oldin ayol kishi tushishi kerak","Kim shoshsa, o‘sha oldin tushadi","Yoshi kichiklar oldin tushishi kerak"],e:"Tushishda erkak oldin, chiqishda ayol oldin."},
 {t:"m",q:"Eskalatorda qayerda turish kerak?",a:["O‘ng tomonda","Chap tomonda","Qoq o‘rtada","Ikki tomonni egallab"],e:"Chap tomon shoshayotganlarga bo‘sh qoldiriladi."},
 {t:"m",q:"Ko‘cha-ko‘yda ayol kishi erkakning qaysi tomonida yuradi?",a:["O‘ng tomonida","Chap tomonida","Orqa tomonida","Oldinroq yurib"],e:"Darslik qoidasiga ko‘ra, o‘ng tomonida."},
 {t:"m",q:"Suv ichish odobiga ko‘ra nima to‘g‘ri?",a:["Bir nafasda emas, uch bo‘lib sekin ichish","Turib yoki yurib, shoshib ichib yuborish","Idishni bo‘shatguncha nafas olmay ichish","Ovoz chiqarib, ho‘plab-ho‘plab ichish"],e:"Suv uch bo‘lib, o‘tirib ichilgani yaxshi."},
 {t:"m",q:"Rahbar bilan salomlashishda xodim qanday yo‘l tutadi?",a:["Rahbar qo‘l uzatmaguncha qo‘l uzatmaydi","Birinchi bo‘lib qo‘lini uzatib, qattiq qisadi","Salom bermasdan, uning gapirishini kutadi","Quchoqlashib, uzoq vaqt qo‘lini qo‘yib yubormaydi"],e:"Subordinatsiya talabi shunday."},
 {t:"m",q:"Nuroniylar bilan qo‘l berib ko‘rishganda nima qilinadi?",a:["Ikki qo‘l uzatib so‘rashiladi","Bir qo‘l bilan silkib qo‘yiladi","Qo‘l qattiq qisib turiladi","Faqat uzoqdan bosh irg‘aladi"],e:"Keksalarga hurmat belgisi sifatida ikki qo‘l uzatiladi."},
 {t:"tf",q:"Etiket qoidasiga ko‘ra, qo‘lni qattiq qisish yoki uzoq qo‘yib yubormaslik hurmat belgisidir.",a:false,e:"Bu odobsizlik hisoblanadi."},
 {t:"tf",q:"Davraga qo‘shilgan odam salom berib kiradi.",a:true,e:"So‘ng mezbon uni ko‘pchilikka tanishtiradi."},
 {t:"tf",q:"Og‘izda luqma bo‘lganda gapirmagan ma’qul.",a:true,e:"Bu dasturxon odobi qoidalaridan."},
 {t:"f",q:"Maktabda yoki mehmondorchilikda amal qiladigan uchta etiket qoidangizni yozib, ahamiyatini tushuntiring.",e:"Kattalarga salom berish, past ovozda gapirish, dasturxonda o‘z oldidan olish; bu hurmat va o‘zaro qulaylikni ta’minlaydi."}]},

{id:"m15",n:"23–24-mavzu",t:"Renessans poydevori",b:4,
 map:{c:"Renessans poydevori",br:[
  {t:"Sharq uyg‘onishi",e:"🏛️",k:["IX–XII asrlar","Ma’mun akademiyasi","Temuriylar"],x:"Ikki Uyg‘onish davri allomalari ilmi Yevropa Renessansiga katta ta’sir ko‘rsatdi."},
  {t:"To‘rt ustun",e:"🧱",k:["tarbiyachi","muallim","professor va ziyolilar"],x:"Yangi Renessans ustunlari — pedagog va ziyolilar; ota-onalar beshinchi ustun."},
  {t:"Formula",e:"⚙️",k:["kuchli iqtisodiyot","kuchli ma’naviyat","poydevor"],x:"Yangi O‘zbekiston = kuchli iqtisodiyot + kuchli ma’naviyat."},
  {t:"Maktab ostonasi",e:"🏫",k:["To‘xtamurod Jumayev","95 foiz","matematika maktabi"],x:"Olis qishloq maktabi yangi metodika bilan respublikaga tanildi."},
  {t:"Ilm va innovatsiya",e:"🚀",k:["Ulug‘bek madrasasi","Beruniy qarashi","stratosfera"],x:"Ilmga intilish farz; innovatsiyaga tayangan davlat yutadi."}]},
 q:[
 {t:"m",q:"Buxorodagi Ulug‘bek madrasasi darvozasiga qaysi mazmundagi hadis yozilgan?",a:["Ilmga intilish har bir musulmon uchun farz","Qo‘shniga yaxshilik qilish iymondan","Tinchlik va xotirjamlik ulug‘ ne’mat","Poklik iymonning yarmidir"],e:"«Ilmga intilish har bir muslim va muslima uchun farzdir»."},
 {t:"m",q:"Yangi Uyg‘onish davrining to‘rt tayanch ustuni qatoriga kim kiradi?",a:["Bog‘cha tarbiyachisi va maktab muallimi","Savdogar va yirik zavod egasi","Sport murabbiyi va muxlislar","Bank xodimi va soliq nazoratchisi"],e:"Tarbiyachi, muallim, professor-o‘qituvchi va ilmiy-ijodiy ziyolilar."},
 {t:"m",q:"Yangi Renessansning beshinchi ustuni kimlar bo‘lishiga ishonch bildirilgan?",a:["Ota-onalar","Tadbirkorlar","Jurnalistlar","Chet ellik ekspertlar"],e:"Prezident ota-onalar beshinchi halqa bo‘lishiga ishonadi."},
 {t:"m",q:"Uchinchi Renessans poydevori formulasi qaysi?",a:["Kuchli iqtisodiyot va kuchli ma’naviyat","Boy tabiiy resurs va arzon ishchi kuchi","Kuchli armiya va baland qal’a devorlari","Chet el kreditlari va keng savdo yo‘llari"],e:"Yangi O‘zbekiston = kuchli iqtisodiyot + kuchli ma’naviyat."},
 {t:"m",q:"Birinchi Uyg‘onish davri allomalarining xizmati qaysi ilmiy maskan faoliyati bilan bog‘langan?",a:["Xorazmdagi Ma’mun akademiyasi","Samarqanddagi Ulug‘bek rasadxonasi","Fas shahridagi Al-Qarovin universiteti","Hirotdagi Navoiy kutubxonasi"],e:"IX–XII asrlar yutuqlari Ma’mun akademiyasi bilan bog‘liq."},
 {t:"m",q:"To‘xtamurod Jumayev maktabi bitiruvchilarining qancha qismi har yili oliy o‘quv yurtiga kiradi?",a:["95 foizdan ortig‘i","75 foizga yaqini","Deyarli yarmi","60 foizi atrofida"],e:"Maktab 2020-yilda Xalqaro matematika maktabiga aylantirildi."},
 {t:"m",q:"«Aql tarozisida o‘lchanmagan bilim haqiqiy emas» fikri kimga tegishli?",a:["Abu Ali ibn Sino","Abu Rayhon Beruniy","Aflotun","Imom Buxoriy"],e:"Darslik bu fikrni qomusiy olim Ibn Sino nomi bilan beradi."},
 {t:"m",q:"Beruniy Kolumb sayohatidan 500 yil oldin qanday qarashni ilgari surgan?",a:["Okeanlar ortida qit’a mavjudligini","Oyda suv va hayot borligini","Yer ostida ulkan dengiz borligini","Quyoshning sovib borayotganini"],e:"U Tinch va Atlantika okeanlari ortida quruqlik borligini taxmin qilgan."},
 {t:"tf",q:"Beruniyga ko‘ra, hukmron kishilarning ilm ahlini hurmat qilishi ilmlar ko‘payishiga sabab bo‘ladi.",a:true,e:"Ilmga rag‘bat va hurmat — iqbol belgisi."},
 {t:"tf",q:"Ziyodulla Butaxonov loyihasi natijasida Yer 42 km balandlikdan suratga olindi.",a:true,e:"2021-yilda yurtimizda ilk bor fazoga aerostat uchirildi."},
 {t:"tf",q:"Aflotun ilm olishda yeb-ichishga chiroq moyidan ko‘proq pul sarflaganini aytgan.",a:false,e:"Aksincha, chiroq moyiga yeb-ichishdan ko‘proq xarajat qilgan."},
 {t:"f",q:"Uchinchi Renessans poydevoriga siz qanday hissa qo‘shmoqchisiz? Rejangizni yozing.",e:"Chuqur bilim va kasb egallash, kitob o‘qish, chet tili va innovatsion g‘oyalar, allomalar merosini o‘rganish."}]},

{id:"m16",n:"25–26-mavzu",t:"Halollik vaksinasi",b:4,
 map:{c:"Halollik vaksinasi",br:[
  {t:"Halollik",e:"💉",k:["poklik","baraka","xotirjamlik"],x:"Halol insonning dili va yo‘li to‘g‘ri, darajasi ulug‘ bo‘ladi."},
  {t:"Kasb mas’uliyati",e:"💼",k:["Azizbek","Zarifa","sotuvchi"],x:"Keyslar ish vaqtini behuda o‘tkazish, mas’uliyat va insofsizlik haqida o‘ylatadi."},
  {t:"Ikki sham",e:"🕯️",k:["davlat mulki","shaxsiy mulk","Umar ibn Xattob"],x:"Davlat shami faqat davlat ishi uchun yoqiladi."},
  {t:"Harom luqma",e:"🍊",k:["xurmo","po‘rtaxol","rozilik"],x:"So‘ramay olingan bir tomchi ham haq: egasining roziligi olinishi kerak."},
  {t:"Korrupsiya",e:"🚫",k:["mansabni suiiste’mol","naf olish","qonunga xilof"],x:"Korrupsiya — mansabdan shaxsiy manfaat yo‘lida qonunga xilof foydalanish."}]},
 q:[
 {t:"m",q:"«Halollik vaksinasi» bilan emlanmasak, nimaga erisha olmasligimiz aytilgan?",a:["O‘zimiz qo‘ygan yuksak marralarga","Sport musobaqalaridagi sovrinlarga","Chet ellarga sayohat qilish imkoniga","Tezda boyib ketish yo‘llariga"],e:"Prezident fikri: aholi halollik bilan «emlanishi» zarur."},
 {t:"m",q:"Azizbek uchun ish kuni nega qiyin o‘tdi?",a:["Tanbehdan keyin ishlamay, vaqtini behuda o‘tkazdi","Bir kunda ikki kishining ishini bajarib charchadi","Kompyuteri buzilib, hisobotni qo‘lda yozib chiqdi","Hamkasblari kelmagani uchun navbatchi bo‘ldi"],e:"U o‘yin va tarmoqlarda vaqt o‘tkazib, soatga qarab o‘tirdi."},
 {t:"m",q:"Do‘kondagi keysda muddati o‘tgan shokoladlar bilan nima qilindi?",a:["Qadog‘idan ochilib, kilogrammlab sotuvga qo‘yildi","Yo‘q qilinib, bu haqda nazorat organiga xabar berildi","Ishlab chiqaruvchiga almashtirish uchun qaytarildi","Xaridorlarga ogohlantirib, bepul tarqatildi"],e:"Bu xaridor sog‘lig‘iga xavf soluvchi insofsizlik."},
 {t:"m",q:"Umar ibn Xattob mehmon bilan suhbatda nega shamni almashtirdi?",a:["Davlat shamini shaxsiy suhbatda yoqmaslik uchun","Birinchi sham juda xira yonib qolgani uchun","Mehmonga alohida hurmat ko‘rsatish uchun","Eski shamni boshqa kunga tejab qo‘yish uchun"],e:"Davlat mulkidan shaxsiy ishda foydalanishni halollik emas deb bildi."},
 {t:"m",q:"«Luqma» hikoyasida fozil inson sotuvchiga nimani buyurdi?",a:["Xurmo egasini topib, rozi qilishni","Qolgan xurmolarni arzon sotishni","Bolalarni do‘kondan haydab yuborishni","Do‘konni boshqa joyga ko‘chirishni"],e:"Birovning tushib qolgan xurmosi bolalarga berilgan edi."},
 {t:"m",q:"«Bigizga aylangan to‘g‘nag‘ich» hikoyasida o‘g‘ilning qilig‘iga nima sabab bo‘lgan deb topildi?",a:["Onasi so‘rovsiz po‘rtaxol sharbatidan tatigani","Otasi bozorda tarozidan urib qolgani","Bolaga qimmat o‘yinchoq olib berilmagani","Qo‘shni bolalarning yomon maslahati"],e:"Homilador ona so‘ralmagan mevadan bir tomchi tatigan; er rozilik olishni aytdi."},
 {t:"m",q:"Qonunga ko‘ra, korrupsiya nima?",a:["Mansabdan naf ko‘rib, qonunga xilof foydalanish","Ish vaqtida shaxsiy telefonda uzoq gaplashish","Tadbirkorning o‘z foydasidan xayriya qilishi","Xodimning qo‘shimcha ish uchun haq olishi"],e:"Shaxsiy yoki o‘zga manfaatini ko‘zlab mavqedan foydalanish va bunday naf berish."},
 {t:"m",q:"Akmal haqidagi keysda qanday muammo ko‘rsatilgan?",a:["Bilimsiz holda tanish orqali ishga joylashish","Bilimli bo‘la turib ish topa olmay qolish","Ish joyidan o‘z xohishi bilan ketib qolish","O‘qishni a’lo bitirib chet elga ketish"],e:"Baholar otasining hurmati uchun qo‘yilgan, ishga ham tanishlik bilan kirgan."},
 {t:"tf",q:"Umar ibn Xattob davlat ishini bajarayotganda davlat shamini yoqqan.",a:true,e:"Shaxsiy suhbatda esa o‘z puliga olingan shamni yoqqan."},
 {t:"tf",q:"Hamshira Zarifani Nazira aya tibbiy ko‘rik uchun minnatdorlik bilan kutib qoldi.",a:false,e:"Ko‘rik haqida gap ochilgach, jahli chiqib, eshikka kuzatdi."},
 {t:"tf",q:"Darslikka ko‘ra, halollik bor joyda haromning yo‘li bekiladi.",a:true,e:"Barcha ezguliklarning boshi halollikdir."},
 {t:"f",q:"Do‘kondor xarid pulini shaxsiy kartasiga o‘tkazishni so‘rasa, nima qilasiz? Javobingizni halollik bilan asoslang.",e:"Rasmiy to‘lov va chek talab qilish: aks holda soliq yashirilishi mumkin; bu davlat va jamiyat haqiga daxl qiladi."}]},

{id:"m17",n:"27–28-mavzu",t:"Havas qil va oldinga intil",b:4,
 map:{c:"Havas qil va oldinga intil",br:[
  {t:"Hasad balosi",e:"🐍",k:["ko‘hna xastalik","g‘araz","kasalliklar"],x:"Hasadgo‘y zimdan ish ko‘radi; hasad o‘z egasining salomatligiga zarar beradi."},
  {t:"Arastu oynasi",e:"🪞",k:["zahri qotil nazar","o‘z aksi","halokat"],x:"Yomon nazar oyna orqali o‘ziga qaytdi."},
  {t:"Ijobiy havas",e:"⭐",k:["ustozlar","orzu","mehnat"],x:"Dilorom Alimova havas va tinimsiz mehnat bilan olima bo‘ldi."},
  {t:"Harakat",e:"🥊",k:["Bahodir Jalolov","Abbos Atoyev","iroda"],x:"Havas va mehnat Jalolovni jahon va Olimpiada chempioni qildi."},
  {t:"Iroda",e:"💪",k:["dadillik","qat’iylik","Farhod Umrzoqov"],x:"Iroda — o‘z faoliyatini boshqara olish qobiliyati."}]},
 q:[
 {t:"m",q:"O‘tkir Hoshimov hasadgo‘yni quturgan itdan qanday farqlaydi?",a:["Hasadgo‘y zimdan, yaxshilarni tanlab zarar yetkazadi","Hasadgo‘y faqat dangal kelib, ochiq hujum qiladi","Hasadgo‘y duch kelgan odamga bir xil munosabatda","Hasadgo‘y birovga umuman zarar yetkaza olmaydi"],e:"It dangal qopadi, hasadgo‘y esa yashirin harakat qiladi."},
 {t:"m",q:"Iskandar zamonidagi jonivorni yengish uchun Arastu nimadan foydalandi?",a:["Katta oynadan","Chuqur o‘radan","Kuchli olovdan","Zaharli o‘qdan"],e:"Jonivor o‘z aksini ko‘rib, o‘z nazarining kasriga uchradi."},
 {t:"m",q:"Arastuga ko‘ra, dunyoda kimning yuki eng og‘ir?",a:["Hasadchining","Yolg‘onchining","Dangasa kishining","Kambag‘al odamning"],e:"Hasadchi boshqalar shodligidan kelgan qayg‘ularni o‘ziga yuklab oladi."},
 {t:"m",q:"Darslikda hasadning davosi sifatida nima ko‘rsatilgan?",a:["Shukur, sabr va yaxshilik bilan oldinga intilish","Raqibning yutug‘ini yashirib, kamsitib gapirish","Muvaffaqiyatli odamlardan o‘ch olishni rejalash","Hech narsaga intilmay, befarq yashab yurish"],e:"Shukur, sabr, kechirimlilik, kek saqlamaslik, kamtarlik va havas."},
 {t:"m",q:"«Niyating – yo‘ldoshing» rivoyatida duoni nopok niyatda o‘rgangan odam nima bo‘ldi?",a:["Suyakdan paydo bo‘lgan sher uni parchaladi","Mashhur tabib bo‘lib, katta boylik orttirdi","Duoni unutib, uyiga eson-omon qaytdi","Tavba qilib, Iso (a.s.) yoniga qaytib keldi"],e:"Yaxshilikdan yomonlik izlash jazosi."},
 {t:"m",q:"Bahodir Jalolovda boksga havas kimning g‘alabalarini kuzatib uyg‘ongan?",a:["Abbos Atoyev","Artur Beterbiyev","Farhod Umrzoqov","Erkabulan Shinaliyev"],e:"2007-yil Chikagodagi chempionatni oila bilan tomosha qilgan."},
 {t:"m",q:"Iroda uchun qaysi kechinma xos?",a:["«Kerak», «bajarishim shart»","«Xohlayman, ammo keyinroq»","«Kimdir qilib bersa edi»","«Omad kelsa, o‘zi bo‘ladi»"],e:"Iroda «men xohlayman» emas, «bajarishim shart» kechinmasidir."},
 {t:"m",q:"Dilorom Alimova fikricha, yaxshi olim bo‘lish uchun bilimdan tashqari nima kerak?",a:["Yaxshi fazilatlar va Vatan tarixini sevish","Nufuzli tanishlar va katta moddiy imkon","Faqat tug‘ma iste’dod va qulay tasodif","Raqiblardan ustun kelish uchun ayyorlik"],e:"Inson fazilatli bo‘lishi, Vatani va tarixini sevishi lozim."},
 {t:"tf",q:"Farhod Umrzoqov baxtsiz hodisadan keyin sportni butunlay tashlab, yutuqqa erishmagan.",a:false,e:"U tosh ko‘tarish bilan shug‘ullanib, jahon rekordi va oltin medallarga erishdi."},
 {t:"tf",q:"Doimiy hasad inson salomatligiga salbiy ta’sir ko‘rsatishi mumkin.",a:true,e:"Asabiylashish turli kasalliklarni keltirib chiqarishi mumkin."},
 {t:"tf",q:"Bahodir Jalolov Tokio–2020 Olimpiadasida boks bo‘yicha oltin medal olgan.",a:true,e:"U 2019-yilda jahon chempioni ham bo‘lgan."},
 {t:"f",q:"Havas bilan hasadning farqi nimada? Hayotdan misol keltiring.",e:"Havas ibrat olib, mehnat bilan intilishga undaydi; hasad boshqaning yutug‘ini ko‘rolmay, zarar istaydi."}]},

{id:"m18",n:"29-mavzu",t:"Mehnatidan qadr topganlar",b:4,
 map:{c:"Mehnatidan qadr topganlar",br:[
  {t:"Ro‘za Kuziyeva",e:"🏋️",k:["paurlifting","kumush medal","cheksiz imkoniyat"],x:"Nogironligiga qaramay Tokio–2020 paralimpiadasida kumush medal oldi."},
  {t:"Bukilmas iroda",e:"🎨",k:["Mavluda","Gulshoda","hunar va biznes"],x:"Mavluda rassomlik va gilamchilikni egalladi, Gulshoda tikuvchilik bilan biznes boshladi."},
  {t:"Galina Melnikova",e:"🎙️",k:["suxandon","doimiy o‘rganish","Vatan"],x:"Mutaxassis — doimiy o‘quvchi; u Vatanim O‘zbekiston deb taklifni rad etgan."},
  {t:"Margarita Filonovich",e:"🏺",k:["arxeolog","Toshkent tarixi","mukofotlar"],x:"Toshkentning 2200 yillik tarixini asosladi."},
  {t:"Al-Qarovin",e:"🎓",k:["Fas shahri","859-yil","Fotima al-Fixriy"],x:"Ayol kishi asos solgan eng qadimiy universitet."}]},
 q:[
 {t:"m",q:"Ro‘za Kuziyeva sportning qaysi turi bilan shug‘ullanadi?",a:["Paurlifting","Suzish","Kamondan otish","Stol tennisi"],e:"U tosh ko‘tarish bilan shug‘ullanadi."},
 {t:"m",q:"Ro‘za Kuziyeva Tokio–2020 paralimpiya o‘yinlarida qanday natijaga erishdi?",a:["Kumush medal oldi","Oltin medal oldi","Bronza medal oldi","To‘rtinchi bo‘ldi"],e:"Tokioda kumush medal sohibi bo‘ldi."},
 {t:"m",q:"Galina Melnikova yoshligida qaysi mutaxassislikni orzu qilgan edi?",a:["Pediatrlikni","Arxeologlikni","Tarjimonlikni","Muallimlikni"],e:"U tibbiyot institutida o‘qib, bolalar shifokori bo‘lishni niyat qilgan."},
 {t:"m",q:"Melnikova suxandonni kimga o‘xshatadi?",a:["Dubulg‘a va qalqonsiz askarga","Yelkansiz qolgan eski kemaga","Parda ortidagi rejissyorga","Savollar beruvchi muallimga"],e:"Suxandonning xato qilishga haqqi yo‘q, vaziyat esa kutilmagan bo‘ladi."},
 {t:"m",q:"Margarita Filonovich tadqiqotlari bilan Toshkent haqida nimani asoslab berdi?",a:["2200 yillik tarixga ega ekanini","Atigi 500 yil oldin qurilganini","Qadimda dengiz bo‘yida bo‘lganini","Marv shahridan ko‘chirilganini"],e:"Shoshtepa, Mingo‘rik va boshqa obidalarni o‘rgangan."},
 {t:"m",q:"Filonovichning arxeologiyaga qiziqishida kimning so‘zi turtki bo‘ldi?",a:["Onasining","Otasining","Dugonasining","Qo‘shnisining"],e:"Onasi yaxshi o‘qisa, tepaliklar sirini ochishini aytgan."},
 {t:"m",q:"Al-Qarovin universitetiga kim asos solgan?",a:["Fotima al-Fixriy","Kibriyo Qahhorova","Saroymulkxonim","Gulandom Subhonova"],e:"Milodiy 859-yilda boy savdogar oilasidan bo‘lgan ayol asos solgan."},
 {t:"m",q:"Al-Qarovin oliy o‘quv dargohi qaysi shaharda joylashgan?",a:["Marokashning Fas shahrida","Misrning Qohira shahrida","Iroqning Bag‘dod shahrida","Suriyaning Damashq shahrida"],e:"U Ginnesning rekordlar kitobiga kiritilgan."},
 {t:"tf",q:"Gulshoda davlatdan 80 million so‘m kredit olib, o‘z biznesini boshlagan.",a:true,e:"2020-yilda u tikuvchilik asosida ish boshladi."},
 {t:"tf",q:"Galina Melnikova Moskvaga ishga taklifni qabul qilib, ko‘chib ketgan.",a:false,e:"U «Vatanim — O‘zbekiston» deb rad etgan."},
 {t:"tf",q:"Ro‘za Kuziyeva o‘z imkoniyatini cheklangan deb hisoblaydi.",a:false,e:"Uning so‘zicha, imkoniyatlari cheksiz."},
 {t:"f",q:"Mavzu qahramonlarini qaysi umumiy fazilatlar birlashtiradi? Ulardan qanday saboq oldingiz?",e:"Mustahkam iroda, tinimsiz mehnat, o‘qish, maqsadga sadoqat; qiyinchilik to‘siq emasligi."}]},

{id:"m19",n:"30-mavzu",t:"Men tanlagan yo‘l",b:4,
 map:{c:"Men tanlagan yo‘l",br:[
  {t:"Yo‘l tanlash",e:"🧭",k:["maqsad","orzu","fazilat"],x:"11 yillik tarbiya mustaqil hayotda maqsad va yo‘l tanlashga tayanch bo‘ladi."},
  {t:"Bugungi jasorat",e:"🦁",k:["g‘oyaviy xurujga qarshilik","halol yashash","daxldorlik"],x:"Halol yashash va Vatan taqdiriga daxldor bo‘lishning o‘zi katta jasorat."},
  {t:"Halollik kaliti",e:"🔑",k:["vijdon posboni","iroda","taraqqiyot"],x:"Halollik taraqqiyot eshiklarini ochadi, ruhni poklaydi."},
  {t:"Hayot qoidalari",e:"📋",k:["manmanliksiz","hasadsiz","xiyonatsiz"],x:"Uch qoida hurmat, xotirjamlik va saodatga yetaklaydi."},
  {t:"Vatan kutadi",e:"📜",k:["G‘afur G‘ulom","a’lo farzand","fanlar"],x:"She’r yoshlarni bilim egallab, Vatan umidini oqlashga chaqiradi."}]},
 q:[
 {t:"m",q:"Darslikda bugungi kunda qaysi ish katta jasorat deb baholanadi?",a:["Halol yashab, Vatan taqdiriga daxldor bo‘lish","Boshqalardan ko‘proq boylik to‘plashga erishish","Har qanday xavfli sarguzashtga o‘ylamay kirishish","O‘z fikrini kuch ishlatib boshqalarga o‘tkazish"],e:"G‘oyaviy xurujlarga qarshi turish va halol yashash ham jasorat."},
 {t:"m",q:"Matnda halollik nimaga o‘xshatiladi?",a:["Sehrli kalitga","Baland qal’aga","Keng daryoga","Tiniq osmonga"],e:"Halollik taraqqiyot eshiklarini ochadigan sehrli kalit."},
 {t:"m",q:"Halollik inson vijdonining nimasi deb ataladi?",a:["Posboni","Raqibi","Soyasi","Mehmoni"],e:"U vijdon posboni, ruhni poklaydigan va irodani mustahkamlaydigan kuch."},
 {t:"m",q:"«Dovyurak va botir insonlar kelajakda sodir bo‘ladigan qiyinchiliklardan qo‘rqmaydi» — kimning so‘zi?",a:["Abu Ali ibn Sino","Jaloliddin Rumiy","Alisher Navoiy","Abu Nasr Forobiy"],e:"Mavzudagi «Ma’naviyat xazinasi»da Ibn Sino fikri keltirilgan."},
 {t:"m",q:"«Darsdan ijobiy saboq» qoidalariga ko‘ra, manmanlikka berilmagan inson nimaga erishadi?",a:["Doimo hurmatda bo‘ladi","Tezda boyib ketadi","Mansabga ko‘tariladi","Mehnatdan ozod bo‘ladi"],e:"«Manmanlikka berilmang, doimo hurmatda bo‘lasiz»."},
 {t:"m",q:"Hasad qilmaslik insonga nima beradi?",a:["Farovonlik va xotirjamlik","Shuhrat va katta mukofot","Boshqalar ustidan hukmronlik","Mehnatsiz keladigan daromad"],e:"«Hech kimga hasad qilmang, farovonlik va xotirjamlik topasiz»."},
 {t:"m",q:"Baxt va saodatga erishish uchun qaysi qoida tavsiya etilgan?",a:["Birovning haqqiga xiyonat qilmaslik","Faqat o‘z manfaatini ustun qo‘yish","Har qanday maslahatni rad etib yurish","Qiyin vazifalarni boshqaga yuklash"],e:"«Birovning haqqiga xiyonat qilmang, baxt va saodatga erishasiz»."},
 {t:"m",q:"«Bilib qo‘yki, seni Vatan kutadi!» she’ri muallifi kim?",a:["G‘afur G‘ulom","Abdulla Oripov","Erkin Vohidov","O‘tkir Hoshimov"],e:"Darslik G‘afur G‘ulomning she’ri bilan yakunlanadi."},
 {t:"tf",q:"Matnga ko‘ra, «Hazrati inson» nomiga sazovor bo‘lish juda oson.",a:false,e:"Tez o‘zgarayotgan dunyoda o‘zlikni saqlab bu nomga loyiq bo‘lish oson emas."},
 {t:"tf",q:"Sharq donishmandlari hikmatida eng katta qashshoqlik bilimsizlik deyiladi.",a:true,e:"Eng katta boylik — aql-zakovat va ilm, meros — yaxshi tarbiya."},
 {t:"tf",q:"Matnga ko‘ra, yuksak inson bo‘lish uchun boshlangan ishga mas’uliyat bilan yondashish shart emas.",a:false,e:"Fidoyilik, har bir ishga mas’uliyat, halollik va vijdon amri zarur deyiladi."},
 {t:"f",q:"Siz tanlagan yo‘l qanday? Maqsadingiz, unga erishish qadamlari va amal qiladigan qoidalaringizni yozing.",e:"Kasb va maqsad, o‘qish rejasi, halollik, mas’uliyat, hasad va manmanlikdan saqlanish, oila va Vatanga foyda keltirish."}]}
);
